// ==========================================================================
// (2026-05-04) — VS_UI_GameCommon.cpp 
//
// Pattern: project_inventory_loop_virtual_call.md +
// project_empty_table_oob_pattern.md
//
// Unprotected access to VS6 legacy (*g_pItemTable)[X][Y].field is common.
// Macro in one place bound check: ITEM_TABLE_VALID(classN, typeN).
// Use:
//   if (ITEM_TABLE_VALID(c, t)) {
//       eType = (*g_pItemTable)[c][t].ElementalType;
//   }
// This way, NULL, empty, and OOB values are checked in a single line.
// ==========================================================================
#define ITEM_TABLE_VALID(classN, typeN) \
    (g_pItemTable != NULL && \
     (classN) >= 0 && (classN) < (int)(*g_pItemTable).GetSize() && \
     (typeN)  >= 0 && (typeN)  < (int)(*g_pItemTable)[classN].GetSize())

// Safe one-shot accessors — return 0 fallback when OOB, used in render loops
// (inline = zero overhead, helper avoids macro double-evaluation hazards)
static inline int SafeReqAdvLevel(int classN, int typeN) {
    return ITEM_TABLE_VALID(classN, typeN) ?
        (*g_pItemTable)[classN][typeN].GetRequireAdvancementLevel() : 0;
}
static inline int SafeReqSUM(int classN, int typeN) {
    return ITEM_TABLE_VALID(classN, typeN) ?
        (*g_pItemTable)[classN][typeN].GetRequireSUM() : 0;
}
static inline int SafeReqLevel(int classN, int typeN) {
    return ITEM_TABLE_VALID(classN, typeN) ?
        (*g_pItemTable)[classN][typeN].GetRequireLevel() : 0;
}

// Safe HName/EName accessor for Format/Init use — returns "" empty string
// (cstring-stable) instead of NULL. Caller passes char* buffers up to caller
// to handle Init/Format with safe lengths.
static inline const char* SafeItemHName(int classN, int typeN) {
    if (!ITEM_TABLE_VALID(classN, typeN)) return "";
    const char* h = (*g_pItemTable)[classN][typeN].HName.GetString();
    return h ? h : "";
}
static inline const char* SafeItemEName(int classN, int typeN) {
    if (!ITEM_TABLE_VALID(classN, typeN)) return "";
    const char* e = (*g_pItemTable)[classN][typeN].EName.GetString();
    return e ? e : "";
}
static inline int SafeItemHNameLen(int classN, int typeN) {
    if (!ITEM_TABLE_VALID(classN, typeN)) return 0;
    return (*g_pItemTable)[classN][typeN].HName.GetLength();
}
static inline int SafeItemENameLen(int classN, int typeN) {
    if (!ITEM_TABLE_VALID(classN, typeN)) return 0;
    return (*g_pItemTable)[classN][typeN].EName.GetLength();
}

