static const char * Phoenix_GetChatIdDivisor(CHAT_LINE_CONDITION condition)
{
	const int index = static_cast<int>(condition);
	if(index < 0 || index >= CLD_TOTAL)
		return ":";

	return g_sz_chat_id_divisor[index];
}

// Text cache transparan key'i magenta olmamali; GDI anti-alias kenarlari
// arka planla harmanlayip pembe sacak olarak ekrana tasiyordu.
static const WORD PHOENIX_CHAT_HISTORY_CACHE_KEY = 0x0001;

static int Phoenix_GetChatFilterMask(const bool chatFilter[CLD_TOTAL])
{
	int mask = 0;
	for(int i = 0; i < CLD_TOTAL; ++i)
	{
		if(chatFilter[i])
			mask |= (1 << i);
	}
	return mask;
}

static bool Phoenix_ChatTextHasInlineMarker(const char *text, int length)
{
	if(text == NULL || length <= 0)
		return false;

	for(int i = 0; i < length; ++i)
	{
		if(text[i] == '^')
			return true;
	}
	return false;
}

static bool Phoenix_ChatTextHasInlineMarker(const char *text)
{
	if(text == NULL)
		return false;

	return Phoenix_ChatTextHasInlineMarker(text, static_cast<int>(strlen(text)));
}

static void Phoenix_FillChatHistoryCache(WORD *bits, int pitchWords, int width, int height)
{
	if(bits == NULL || pitchWords <= 0 || width <= 0 || height <= 0)
		return;

	for(int y = 0; y < height; ++y)
	{
		WORD *row = bits + y * pitchWords;
		for(int x = 0; x < width; ++x)
			row[x] = PHOENIX_CHAT_HISTORY_CACHE_KEY;
	}
}

static void Phoenix_SetCachedTextFormat(HDC hdc, const PrintInfo &pi, COLORREF color)
{
	SelectObject(hdc, pi.hfont);
	SetTextAlign(hdc, pi.text_align);
	SetBkMode(hdc, pi.bk_mode);
	SetBkColor(hdc, pi.back_color);
	SetTextColor(hdc, color);
}

static int Phoenix_DrawCachedTextLen(HDC hdc, int x, int y, const char *text, int length, const PrintInfo &pi, COLORREF color)
{
	if(hdc == NULL || text == NULL || length <= 0)
		return x;

	Phoenix_SetCachedTextFormat(hdc, pi, color);
	Phoenix_TextOutDW(hdc, x, y, text, length);  // Faz T3

	SIZE textSize = {0, 0};
	GetTextExtentPoint32(hdc, text, length, &textSize);
	return x + textSize.cx;
}

static int Phoenix_DrawCachedText(HDC hdc, int x, int y, const char *text, const PrintInfo &pi, COLORREF color)
{
	if(text == NULL)
		return x;

	return Phoenix_DrawCachedTextLen(hdc, x, y, text, static_cast<int>(strlen(text)), pi, color);
}

enum
{
	PHOENIX_CHAT_STYLE_BOLD = 0x1,
	PHOENIX_CHAT_STYLE_ITALIC = 0x2,
	PHOENIX_CHAT_STYLE_UNDERLINE = 0x4,
};

static COLORREF Phoenix_GetCachedChatColor(char code, COLORREF defaultColor)
{
	switch(code)
	{
	case 'Y': case 'y': return RGB(255, 220, 0);
	case 'R': case 'r': return RGB(255, 60, 60);
	case 'G': case 'g': return RGB(80, 220, 80);
	case 'N': case 'n': return RGB(80, 160, 255);
	case 'W': case 'w': return RGB(255, 255, 255);
	case 'K': case 'k': return RGB(0, 0, 0);
	case 'O': case 'o': return RGB(255, 140, 0);
	case 'P': case 'p': return RGB(200, 100, 240);
	default: return defaultColor;
	}
}

static HFONT Phoenix_GetCachedChatStyledFont(HFONT baseFont, int styleBits)
{
	if(baseFont == NULL || styleBits == 0)
		return baseFont;

	static std::map<HFONT, std::array<HFONT, 8> > s_styledFontCache;
	std::map<HFONT, std::array<HFONT, 8> >::iterator it = s_styledFontCache.find(baseFont);
	if(it == s_styledFontCache.end())
	{
		std::array<HFONT, 8> fonts;
		fonts.fill(NULL);
		fonts[0] = baseFont;
		it = s_styledFontCache.insert(std::make_pair(baseFont, fonts)).first;
	}

	if(styleBits < 0 || styleBits >= static_cast<int>(it->second.size()))
		return baseFont;

	if(it->second[styleBits] == NULL)
	{
		LOGFONT lf;
		if(GetObject(baseFont, sizeof(lf), &lf) > 0)
		{
			if(styleBits & PHOENIX_CHAT_STYLE_BOLD)
				lf.lfWeight = FW_BOLD;
			if(styleBits & PHOENIX_CHAT_STYLE_ITALIC)
				lf.lfItalic = TRUE;
			if(styleBits & PHOENIX_CHAT_STYLE_UNDERLINE)
				lf.lfUnderline = TRUE;

			it->second[styleBits] = CreateFontIndirect(&lf);
		}
	}

	return it->second[styleBits] != NULL ? it->second[styleBits] : baseFont;
}

static int Phoenix_DrawCachedTaggedTextLen(HDC hdc, int x, int y, const char *text, int length, const PrintInfo &pi, COLORREF color)
{
	if(hdc == NULL || text == NULL || length <= 0)
		return x;

	if(!Phoenix_ChatTextHasInlineMarker(text, length))
		return Phoenix_DrawCachedTextLen(hdc, x, y, text, length, pi, color);

	SetTextAlign(hdc, pi.text_align);
	SetBkMode(hdc, pi.bk_mode);
	SetBkColor(hdc, pi.back_color);

	const HFONT baseFont = pi.hfont;
	const COLORREF defaultColor = color;
	COLORREF currentColor = defaultColor;
	int currentStyle = 0;
	int currentX = x;
	char buffer[1024];
	int bufferLength = 0;

	auto flushSegment = [&]()
	{
		if(bufferLength <= 0)
			return;

		buffer[bufferLength] = '\0';
		HFONT font = Phoenix_GetCachedChatStyledFont(baseFont, currentStyle);
		SelectObject(hdc, font);
		SetTextColor(hdc, RGB(0, 0, 0));
		Phoenix_TextOutDW(hdc, currentX + 1, y + 1, buffer, bufferLength);  // Faz T3
		SetTextColor(hdc, currentColor);
		Phoenix_TextOutDW(hdc, currentX, y, buffer, bufferLength);

		SIZE textSize = {0, 0};
		GetTextExtentPoint32(hdc, buffer, bufferLength, &textSize);
		currentX += textSize.cx;
		bufferLength = 0;
	};

	for(int i = 0; i < length; ++i)
	{
		const char c = text[i];
		if(c == '^' && i + 1 < length)
		{
			const char next = text[i + 1];
			if(next == '^')
			{
				if(bufferLength >= static_cast<int>(sizeof(buffer)) - 1)
				{
					flushSegment();
				}
				buffer[bufferLength++] = '^';
				++i;
				continue;
			}

			if(next == '!' && i + 2 < length)
			{
				flushSegment();

				const char code = text[i + 2];
				switch(code)
				{
				case 'Y': case 'y':
				case 'R': case 'r':
				case 'G': case 'g':
				case 'N': case 'n':
				case 'W': case 'w':
				case 'K': case 'k':
				case 'O': case 'o':
				case 'P': case 'p':
					currentColor = Phoenix_GetCachedChatColor(code, defaultColor);
					break;
				case 'B': case 'b':
					currentStyle ^= PHOENIX_CHAT_STYLE_BOLD;
					break;
				case 'I': case 'i':
					currentStyle ^= PHOENIX_CHAT_STYLE_ITALIC;
					break;
				case 'U': case 'u':
					currentStyle ^= PHOENIX_CHAT_STYLE_UNDERLINE;
					break;
				case '-':
					currentColor = defaultColor;
					currentStyle = 0;
					break;
				default:
					break;
				}

				i += 2;
				continue;
			}
		}

		if(bufferLength >= static_cast<int>(sizeof(buffer)) - 1)
		{
			flushSegment();
		}
		buffer[bufferLength++] = c;
	}

	flushSegment();
	return currentX;
}

static int Phoenix_DrawCachedTaggedText(HDC hdc, int x, int y, const char *text, const PrintInfo &pi, COLORREF color)
{
	if(text == NULL)
		return x;

	if(!Phoenix_ChatTextHasInlineMarker(text))
		return Phoenix_DrawCachedText(hdc, x, y, text, pi, color);

	return Phoenix_DrawCachedTaggedTextLen(hdc, x, y, text, static_cast<int>(strlen(text)), pi, color);
}

void C_VS_UI_CHAT_LINE::InvalidateRenderCache() const
{
	m_render_cache_valid = false;
	m_render_cache_width = -1;
	m_render_cache_id_gap = 0;
	m_render_cache_id_font = NULL;
	m_render_cache_chat_font = NULL;
	m_render_cache_divisor = NULL;
	m_render_cache_id_width = 0;
	m_render_cache_divisor_width = 0;
	m_render_cache_message_length = 0;
	m_render_cache_cut_lengths.clear();
}

void C_VS_UI_CHAT_LINE::PrepareRenderCache(int chatWindowWidth, int idGap, const char * divisor, HFONT idFont, HFONT chatFont) const
{
	if(m_render_cache_valid &&
		m_render_cache_width == chatWindowWidth &&
		m_render_cache_id_gap == idGap &&
		m_render_cache_id_font == idFont &&
		m_render_cache_chat_font == chatFont &&
		m_render_cache_divisor == divisor)
	{
		return;
	}

	m_render_cache_valid = true;
	m_render_cache_width = chatWindowWidth;
	m_render_cache_id_gap = idGap;
	m_render_cache_id_font = idFont;
	m_render_cache_chat_font = chatFont;
	m_render_cache_divisor = divisor;
	const char *idString = GetIdString();
	const char *divisorString = divisor ? divisor : "";
	const bool hasIdString = (idString != NULL && idString[0] != '\0');

	m_render_cache_id_width = hasIdString ? g_GetStringWidth(idString, idFont) : 0;
	m_render_cache_divisor_width = hasIdString ? g_GetStringWidth(divisorString, chatFont) : 0;
	m_render_cache_message_length = 0;
	m_render_cache_cut_lengths.clear();

	const char * message = GetMsgString();
	if(message == NULL)
		return;

	int cut_length = 0;
	m_render_cache_message_length = static_cast<int>(strlen(message));

	if(GetCondition() == CLD_ZONECHAT)
	{
		const int smart_size = chatWindowWidth - m_render_cache_id_width - m_render_cache_divisor_width - idGap;
		cut_length = m_render_cache_message_length;

		if(g_GetStringWidth(message, idFont) > smart_size)
		{
			std::vector<char> temp(message, message + m_render_cache_message_length + 1);
			while(cut_length > 0 && g_GetStringWidth(&temp[0], idFont) > smart_size)
			{
				temp[cut_length--] = '\0';
			}
		}
	}
	else
	{
		int char_width = g_GetStringWidth("F", chatFont);
		if(char_width <= 0)
			char_width = 1;

		cut_length = (chatWindowWidth - m_render_cache_id_width - m_render_cache_divisor_width - idGap) / char_width;
	}

	if(cut_length <= 0)
		cut_length = 1;

	if(cut_length < m_render_cache_message_length)
	{
		int consumed = 0;
		while(m_render_cache_message_length - consumed > cut_length)
		{
			int len = cut_length;
			int cutPos = consumed + len;

			if(cutPos > 0 && !g_PossibleStringCut(message, cutPos))
			{
				--cutPos;
				--len;
			}

			if(len <= 0)
			{
				len = cut_length;
				cutPos = consumed + len;
			}

			m_render_cache_cut_lengths.push_back(len);
			consumed += len;

			if(consumed >= m_render_cache_message_length)
				break;
		}

		const int remaining = m_render_cache_message_length - consumed;
		if(remaining > 0)
			m_render_cache_cut_lengths.push_back(remaining);
	}
	else
	{
		m_render_cache_cut_lengths.push_back(m_render_cache_message_length);
	}
}

