C_VS_UI_TRIBE::C_VS_UI_TRIBE()
{
	CT_Done("DIAG: C_VS_UI_TRIBE ctor enter");


	//AttrTopmost(false);//false);


	g_RegisterWindow(this);

	AttrKeyboardControl(true);

	AttrPin(true);
	CT_Done("DIAG: C_VS_UI_TRIBE pre new C_VS_UI_INVENTORY");
	m_pC_inventory = new C_VS_UI_INVENTORY;
	CT_Done("DIAG: C_VS_UI_TRIBE post C_VS_UI_INVENTORY=%p", m_pC_inventory);
	m_pC_quest_status = new C_VS_UI_QUEST_STATUS;
	CT_Done("DIAG: C_VS_UI_TRIBE post C_VS_UI_QUEST_STATUS=%p", m_pC_quest_status);

	m_pC_hpbar = new C_VS_UI_HPBAR;
	CT_Done("DIAG: C_VS_UI_TRIBE post C_VS_UI_HPBAR=%p", m_pC_hpbar);
	m_pC_BloodBurst = new C_VS_UI_BLOOD_BURST;
	CT_Done("DIAG: C_VS_UI_TRIBE post C_VS_UI_BLOOD_BURST=%p", m_pC_BloodBurst);

	//m_pC_Market =  new  C_VS_UI_MARKET_ACCOUNT ;
	m_pC_ShortCutSlot = new C_VS_UI_SHORTCUT_SLOT;
	CT_Done("DIAG: C_VS_UI_TRIBE post C_VS_UI_SHORTCUT_SLOT=%p", m_pC_ShortCutSlot);

	m_pC_effect_status = new C_VS_UI_EFFECT_STATUS;
	CT_Done("DIAG: C_VS_UI_TRIBE post C_VS_UI_EFFECT_STATUS=%p", m_pC_effect_status);
	m_pc_tmall = new C_VS_UI_TMALL;
	CT_Done("DIAG: C_VS_UI_TRIBE post C_VS_UI_TMALL=%p", m_pc_tmall);
	m_pc_payevent = new C_VS_UI_PAYEVENT;
	CT_Done("DIAG: C_VS_UI_TRIBE post C_VS_UI_PAYEVENT=%p", m_pc_payevent);
	m_pC_minimap = new C_VS_UI_MINIMAP;
	CT_Done("DIAG: C_VS_UI_TRIBE post C_VS_UI_MINIMAP=%p", m_pC_minimap);
	//m_pc_gamehook = new C_VS_UI_GAMEHOOK;
	m_pc_hollywar = new C_VS_UI_HOLYWAR;
	CT_Done("DIAG: C_VS_UI_TRIBE post C_VS_UI_HOLYWAR=%p", m_pc_hollywar);

	m_pc_military = new C_VS_UI_MILITARYDLG;
	CT_Done("DIAG: C_VS_UI_TRIBE post C_VS_UI_MILITARYDLG=%p", m_pc_military);

	m_pC_chatting = NULL;
	m_pC_skill = new C_VS_UI_SKILL;
	CT_Done("DIAG: C_VS_UI_TRIBE post C_VS_UI_SKILL=%p", m_pC_skill);

	// 2026-09-03 — skill hizli butonu minimap grubuna baglanir (kullanici
	// istegi: minimap tasininca skill butonu birlikte gitmeli). Offset,
	// legacy default yerlesimden hesaplanir: skill (resX-248-42, resY-156),
	// minimap ctor default'u (resX-w-2, resY-h-2). Boylece varsayilan
	// gorunum pixel-pixel ayni kalir, tasima grup halinde olur.
	{
		const int skillDefX = g_pUserInformation->iResolution_x - 248 - 42;
		const int skillDefY = g_pUserInformation->iResolution_y - 156;
		m_pC_minimap->SetSkillFollow(m_pC_skill,
			skillDefX - m_pC_minimap->x, skillDefY - m_pC_minimap->y);
	}
//	m_pC_hide_button = new ButtonGroup(this);
	
	m_pC_level_up = NULL;
	
	// TIMER
	m_dw_prev_tickcount = GetTickCount();
	m_dw_millisec = 100;

	m_OpenedHelpIdx = EXEC_MAX;
	
	m_selected_menu = -1;

	//m_bl_hide = false;
	
}

