void	C_VS_UI_TRIBE::Show()
{
	CT_Done("WnSh: C_VS_UI_TRIBE::Show ENTER pthis=%p main_spk=%p", (void*)this, (void*)m_pC_main_spk);
	Phoenix_FrameProbeStageScope fpTribeTotal("Tribe.Show.Total", g_hWnd, (int)g_bActiveApp, (int)g_bActiveGame);

	CT_Done("TR: pre GetWidth SIMPLE_MAIN");
	int mainW = m_pC_main_spk->GetWidth(SIMPLEINFOMATION_MAIN);
	CT_Done("TR: post mainW=%d, pre GetWidth SIMPLE_TIME_BACK", mainW);
	int timeW = m_pC_main_spk->GetWidth(SIMPLEINFOMATION_TIME_BACKGROUD);
	CT_Done("TR: post timeW=%d", timeW);
	int imgX=(mainW-timeW)/2;
	CT_Done("TR: imgX=%d, pre Lock", imgX);
	if(gpC_base->m_p_DDSurface_back->Lock())
	{
		Phoenix_FrameProbeStageScope fpTribeLocked("Tribe.Show.LockedSprites", g_hWnd, (int)g_bActiveApp, (int)g_bActiveGame);
			CT_Done("TR: post Lock OK, pre BltLocked SIMPLE_MAIN");
			m_pC_main_spk->BltLocked(x, y, SIMPLEINFOMATION_MAIN);
			CT_Done("TR: post BltLocked SIMPLE_MAIN");

			int sec = 0, min = 0, hour = 0;
			char sz_temp[20];
			strcpy(sz_temp, m_time.c_str());
			sec = atoi(sz_temp+strlen(sz_temp)-2);
			sz_temp[strlen(sz_temp)-3] = '\0';
			min = atoi(sz_temp+strlen(sz_temp)-2);
			sz_temp[strlen(sz_temp)-3] = '\0';
			hour = atoi(sz_temp);

			m_pC_main_spk->BltLocked(x+imgX,y+35,SIMPLEINFOMATION_TIME_BACKGROUD);

			if(hour >=8 && hour<20)
			{
				m_pC_main_spk->BltLocked(x+imgX,y+35,SIMPLEINFOMATION_TIME_SUN);
				m_pC_main_spk->BltLocked(x+imgX+m_pC_main_spk->GetWidth(SIMPLEINFOMATION_TIME_SUN)-3,y+30,SIMPLEINFOMATION_SUN);

				if(hour >=16 && hour <20)
				{
					int time = (hour-16)*60+min;
					Rect rect(0, 0, m_pC_main_spk->GetWidth(SIMPLEINFOMATION_TIME_MOON)-m_pC_main_spk->GetWidth(SIMPLEINFOMATION_TIME_MOON)*(240-time)/240, m_pC_main_spk->GetHeight(SIMPLEINFOMATION_TIME_MOON));
					m_pC_main_spk->BltLockedClip(x+imgX, y+35, rect, SIMPLEINFOMATION_TIME_MOON);
					m_pC_main_spk->BltLocked(x+imgX+m_pC_main_spk->GetWidth(SIMPLEINFOMATION_TIME_MOON)-m_pC_main_spk->GetWidth(SIMPLEINFOMATION_TIME_MOON)*(240-time)/240-3,y+30,SIMPLEINFOMATION_MOON);
				}
			}
			else if(hour >= 20 || hour < 8)
			{
				m_pC_main_spk->BltLocked(x+imgX,y+35,SIMPLEINFOMATION_TIME_MOON);
				m_pC_main_spk->BltLocked(x+imgX+m_pC_main_spk->GetWidth(SIMPLEINFOMATION_TIME_MOON)-3,y+30,SIMPLEINFOMATION_MOON);

				if(hour >=4 && hour < 8)
				{
					int time = (hour-4)*60+min;
					Rect rect(0, 0, m_pC_main_spk->GetWidth(SIMPLEINFOMATION_TIME_MOON)-m_pC_main_spk->GetWidth(SIMPLEINFOMATION_TIME_MOON)*(240-time)/240, m_pC_main_spk->GetHeight(SIMPLEINFOMATION_TIME_MOON));
					m_pC_main_spk->BltLockedClip(x+imgX, y+35, rect, SIMPLEINFOMATION_TIME_SUN);
					m_pC_main_spk->BltLocked(x+imgX+m_pC_main_spk->GetWidth(SIMPLEINFOMATION_TIME_MOON)-m_pC_main_spk->GetWidth(SIMPLEINFOMATION_TIME_MOON)*(240-time)/240-3,y+30,SIMPLEINFOMATION_SUN);
				}
			}	

	
//		m_pC_hide_button->Show();
		CT_Done("TR: pre Unlock");
		gpC_base->m_p_DDSurface_back->Unlock();
		CT_Done("TR: post Unlock");
	}
	else
	{
		CT_Done("TR: Lock FAILED");
	}

	CT_Done("TR: pre FL2_GetDC");
	{
		Phoenix_FrameProbeStageScope fpTribeTimeText("Tribe.Show.TimeText", g_hWnd, (int)g_bActiveApp, (int)g_bActiveGame);
		g_FL2_GetDC();
		CT_Done("TR: post FL2_GetDC, pre PrintColorStr date");
		//m_pC_hide_button->ShowDescription();
		//m_pC_common_button_group->ShowDescription();

		g_PrintColorStr(x+53, y+18, m_date.c_str() ,gpC_base->m_chatting_pi, RGB_WHITE);
		CT_Done("TR: post PrintColorStr date, pre PrintColorStr time");
		g_PrintColorStr(x+53+20+g_GetStringWidth(m_date.c_str(), gpC_base->m_chatting_pi.hfont), y+18, m_time.c_str(), gpC_base->m_chatting_pi, RGB_WHITE);
		CT_Done("TR: post PrintColorStr time, pre FL2_ReleaseDC");
		g_FL2_ReleaseDC();
	}
	CT_Done("TR: post FL2_ReleaseDC, pre ShowExp (virtual)");


	//////////////////////////////////////////////////////////////////////////
	// �� ������ ����ġ ǥ��

	{
		Phoenix_FrameProbeStageScope fpTribeExp("Tribe.Show.Exp", g_hWnd, (int)g_bActiveApp, (int)g_bActiveGame);
		ShowExp();
	}
	CT_Done("TR: post ShowExp, pre m_pC_skill->Show2 m_pC_skill=%p", (void*)m_pC_skill);

	//
	//////////////////////////////////////////////////////////////////////////

	{
		Phoenix_FrameProbeStageScope fpTribeSkill("Tribe.Show.SkillShow2", g_hWnd, (int)g_bActiveApp, (int)g_bActiveGame);
		m_pC_skill->Show2();
	}
	CT_Done("TR: post Show2, EXIT");
}

void	C_VS_UI_TRIBE::Process()
{
	if(!m_pC_skill->IsPixel(gpC_mouse_pointer->GetX(), gpC_mouse_pointer->GetY()))
	{
		ProcessHide(68);
	}
//	m_pC_hide_button->Process();
}

void	C_VS_UI_TRIBE::WindowEventReceiver(id_t event)
{
	switch (event)
	{
	case EVENT_WINDOW_MOVE:
		// 2026-09-03 — skill butonu artik minimap grubunda konumlanir
		// (C_VS_UI_MINIMAP::UpdateSkillFollowPosition; kullanici istegi).
		// Eski TRIBE'a bagli konumlama devre disi:
		//	m_pC_skill->SetStartPoint(x+g_pUserInformation->iResolution_x-248-42, g_pUserInformation->iResolution_y-156);
		// Panel tasinirken minimap'in follow konumu tazelenir ki race
		// Start'taki ilk yerlesim de ayni yoldan gecsin.
		if (m_pC_minimap != NULL)
			m_pC_minimap->UpdateSkillFollowPosition();
		EMPTY_MOVE;
		break;
	}
}
