void	C_VS_UI_TRIBE::ShowButtonWidget(C_VS_UI_EVENT_BUTTON * p_button)
{
		if(p_button->GetID() == SUB_MENU_BOTTOM)
		{
			if(p_button->GetFocusState())
			{
				if(p_button->GetPressState())
					m_pC_main_spk->BltLocked(x+p_button->x, y+p_button->y+1, SIMPLEINFOMATION_HIDE);
				else
					m_pC_main_spk->BltLocked(x+p_button->x, y+p_button->y, SIMPLEINFOMATION_HIDE_DOWN);
			}
			else
				m_pC_main_spk->BltLocked(x+p_button->x, y+p_button->y,SIMPLEINFOMATION_HIDE_DOWN);
		}
	
}

