void	
C_VS_UI_TRIBE::ShopRunningAnnounced() // Shop�� ���� �ʿ��� Window�� ����.
{
	POINT ptOffset = {
		(RESOLUTION_X - 800) / 2, (RESOLUTION_Y - 600) / 2
	};

	switch(g_eRaceInterface)
	{
	case RACE_SLAYER:
		InventoryXY(380 + ptOffset.x, 85 + ptOffset.y);
		break;

	case RACE_VAMPIRE:
		InventoryXY(380 + ptOffset.x, 80 + ptOffset.y);
		break;

	case RACE_OUSTERS:
		InventoryXY(380 + ptOffset.x, 80 + ptOffset.y);
		break;
	}	
	OpenInventory(false);
}


