void	C_VS_UI_TRIBE::HotKey_Grade1Info()
{
	CT_HOTKEY("C_VS_UI_TRIBE::HotKey_Grade1Info entry gpC_base=%p eventOccured=%d runningGrade1=%d race=%d",
		(void*)gpC_base,
		(gpC_base != NULL && gpC_base->EventOccured() == true) ? 1 : 0,
		gC_vs_ui.IsRunningGrade1Info() ? 1 : 0,
		(int)g_eRaceInterface);

	if (gpC_base == NULL || gpC_base->EventOccured() == true)
	{
		CT_HOTKEY("C_VS_UI_TRIBE::HotKey_Grade1Info return: gpC_base null or event occurred");
		return;
	}
	
	switch(g_eRaceInterface)
	{
	case RACE_SLAYER:
		PlaySound(SOUND_SLAYER_BUTTON);
		break;

	case RACE_VAMPIRE:
		PlaySound(SOUND_VAMPIRE_BUTTON);
		break;

	case RACE_OUSTERS:
		PlaySound(SOUND_OUSTERS_INTERFACE);
		break;
	}	
	
	if(gC_vs_ui.IsRunningGrade1Info())
	{
		CT_HOTKEY("C_VS_UI_TRIBE::HotKey_Grade1Info closing existing Grade1 info");
		gC_vs_ui.CloseInfo();
	}
	else
	{
		CT_HOTKEY("C_VS_UI_TRIBE::HotKey_Grade1Info RunInfo(GRADE1_INFO_MODE)");
		gC_vs_ui.RunInfo(C_VS_UI_INFO::GRADE1_INFO_MODE);
	}
}

