bool C_VS_UI_TRIBE::Timer()
{
	if(m_dw_prev_tickcount+m_dw_millisec <= GetTickCount())
	{
		m_dw_prev_tickcount = GetTickCount();
		return true;
	}
	
	return false;
}

bool C_VS_UI_TRIBE::MouseControl(UINT message, int _x, int _y)
{
		Window::MouseControl(message, _x, _y);
	_x -= x; _y -= y;

			if(g_eRaceInterface == RACE_SLAYER)
			{	
				const int bar_x = 50, bar_y = 130, str_x = 176, str_y = 8;
				if(_x>=49 && _x<=227 && _y >= 130 && _y <= 138)
				{   				
					static std::string hpbar_string[2];
					const static char *help_string[3] = {NULL, NULL, NULL};
					char temp_string[512];

					help_string[1] = NULL;
					help_string[2] = NULL;

					int exp_remain = g_char_slot_ingame.EXP_REMAIN;

					if(g_char_slot_ingame.m_AdvancementLevel>0)
					{

						wsprintf(temp_string,"Adv Level:%d", g_char_slot_ingame.m_AdvancementLevel);
					}
					else
					{

						wsprintf(temp_string,(*g_pGameStringTable)[UI_STRING_MESSAGE_HPBAR_LEVEL_DESCRIPTION].GetString(), g_char_slot_ingame.level);
					}

					hpbar_string[0]=temp_string;

					int fame = g_pFameInfoTable->GetFameForLevel( SKILLDOMAIN_VAMPIRE, g_char_slot_ingame.level );

					if(exp_remain < 0)
					{
						hpbar_string[1]=(*g_pGameStringTable)[UI_STRING_MESSAGE_CANNOT_UP_LEVEL].GetString();					
					}
					else if(g_char_slot_ingame.FAME < fame)
					{
						wsprintf(temp_string, "%s(%s:%d)",(*g_pGameStringTable)[UI_STRING_MESSAGE_CANNOT_UP_LEVEL_BY_FAME].GetString(), 
							(*g_pGameStringTable)[UI_STRING_MESSAGE_NEED_FAME].GetString(), 
							fame- g_char_slot_ingame.FAME);
						hpbar_string[1] = temp_string;
					}
					else
					{
						__int64 goal_exp =  max(1, g_pExperienceTable->GetAdvanceMent(g_char_slot_ingame.m_AdvancementLevel).GoalExp);

						// 2026-05-18 FIX: arg2 percentage hesaplanmali (eski: raw goal_exp = "4922%" gibi).
						// Format string: "Remaining EXP : %s (%s%%)" — arg2 = percent string.
						__int64 percent = (goal_exp - exp_remain) * 100 / max((__int64)1, goal_exp);
						wsprintf(temp_string, (*g_pGameStringTable)[UI_STRING_MESSAGE_HPBAR_EXP_DESCRIPTION_NEW].GetString(), g_GetNumberString(exp_remain).c_str(), g_GetNumberString(percent).c_str());
						hpbar_string[1]=temp_string;
					}

					help_string[0] = hpbar_string[0].c_str();
					help_string[2] = hpbar_string[1].c_str();

					g_descriptor_manager.Set(DID_HELP, x+30, y+100, (void *)help_string, 0, 0);

				}
			}
			else if(g_eRaceInterface == RACE_OUSTERS)
			{
				const int bar_x = 50, bar_y = 130, str_x = 176, str_y = 8;
				if(_x>=49 && _x<=227 && _y >= 130 && _y <= 138)
				{
					static std::string hpbar_string[2];
					const static char *help_string[3] = {NULL, NULL, NULL};

					char temp_string[512];

					help_string[1] = NULL;
					help_string[2] = NULL;

					int exp_remain = g_char_slot_ingame.EXP_REMAIN;

					if(g_char_slot_ingame.m_AdvancementLevel>0)
					{

						wsprintf(temp_string,"Adv Level:%d", g_char_slot_ingame.m_AdvancementLevel);
					}
					else
					{

						wsprintf(temp_string,(*g_pGameStringTable)[UI_STRING_MESSAGE_HPBAR_LEVEL_DESCRIPTION].GetString(), g_char_slot_ingame.level);
					}

					hpbar_string[0]=temp_string;

					int fame = g_pFameInfoTable->GetFameForLevel( SKILLDOMAIN_VAMPIRE, g_char_slot_ingame.level );

					if(exp_remain < 0)
					{
						hpbar_string[1]=(*g_pGameStringTable)[UI_STRING_MESSAGE_CANNOT_UP_LEVEL].GetString();					
					}
					else if(g_char_slot_ingame.FAME < fame)
					{
						wsprintf(temp_string, "%s(%s:%d)",(*g_pGameStringTable)[UI_STRING_MESSAGE_CANNOT_UP_LEVEL_BY_FAME].GetString(), 
							(*g_pGameStringTable)[UI_STRING_MESSAGE_NEED_FAME].GetString(), 
							fame- g_char_slot_ingame.FAME);
						hpbar_string[1] = temp_string;
					}
					else
					{
						__int64 goal_exp =  max(1, g_pExperienceTable->GetAdvanceMent(g_char_slot_ingame.m_AdvancementLevel).GoalExp);

						// 2026-05-18 FIX: 3 irk pariteli percentage fix (Ousters bloku).
						__int64 percent = (goal_exp - exp_remain) * 100 / max((__int64)1, goal_exp);
						wsprintf(temp_string, (*g_pGameStringTable)[UI_STRING_MESSAGE_HPBAR_EXP_DESCRIPTION_NEW].GetString(), g_GetNumberString(exp_remain).c_str(), g_GetNumberString(percent).c_str());
						hpbar_string[1]=temp_string;
					}

					help_string[2] = hpbar_string[1].c_str();
					help_string[0] = hpbar_string[0].c_str();
					g_descriptor_manager.Set(DID_HELP, x+bar_x, y+bar_y, (void *)help_string);
				}
			}
			else if(g_eRaceInterface == RACE_VAMPIRE)
			{
				const int bar_x = 50, bar_y = 130, str_x = 176, str_y = 8;
				if(_x>=49 && _x<=227 && _y >= 130 && _y <= 138)
				{

					static std::string hpbar_string[2];
					const static char *help_string[3] = {NULL, NULL, NULL};
					char temp_string[512];

					help_string[1] = NULL;
					help_string[2] = NULL;

					int exp_remain = g_char_slot_ingame.EXP_REMAIN;

					if(g_char_slot_ingame.m_AdvancementLevel>0)
					{

						wsprintf(temp_string,"Adv Level:%d", g_char_slot_ingame.m_AdvancementLevel);
					}
					else
					{

						wsprintf(temp_string,(*g_pGameStringTable)[UI_STRING_MESSAGE_HPBAR_LEVEL_DESCRIPTION].GetString(), g_char_slot_ingame.level);
					}

					hpbar_string[0]=temp_string;

					int fame = g_pFameInfoTable->GetFameForLevel( SKILLDOMAIN_VAMPIRE, g_char_slot_ingame.level );

					if(exp_remain < 0)
					{
						hpbar_string[1]=(*g_pGameStringTable)[UI_STRING_MESSAGE_CANNOT_UP_LEVEL].GetString();					
					}
					else if(g_char_slot_ingame.FAME < fame)
					{
						wsprintf(temp_string, "%s(%s:%d)",(*g_pGameStringTable)[UI_STRING_MESSAGE_CANNOT_UP_LEVEL_BY_FAME].GetString(), 
							(*g_pGameStringTable)[UI_STRING_MESSAGE_NEED_FAME].GetString(), 
							fame- g_char_slot_ingame.FAME);
						hpbar_string[1] = temp_string;
					}
					else
					{
						const ExpInfo* expinf = &g_pExperienceTable->GetVampireInfo(g_char_slot_ingame.level);
						__int64 goal_exp = expinf->GoalExp;

						// 2026-05-18 FIX: 3 irk pariteli percentage fix (Vampire bloku).
						// Bu kullanicinin screenshot'inda gozlemledigi bug: "(4,922%)" raw goal.
						__int64 percent = (goal_exp - exp_remain) * 100 / max((__int64)1, goal_exp);
						wsprintf(temp_string, (*g_pGameStringTable)[UI_STRING_MESSAGE_HPBAR_EXP_DESCRIPTION_NEW].GetString(), g_GetNumberString(exp_remain).c_str(), g_GetNumberString(percent).c_str());
						hpbar_string[1]=temp_string;
					}

					help_string[0] = hpbar_string[0].c_str();
					help_string[2] = hpbar_string[1].c_str();

					g_descriptor_manager.Set(DID_HELP, x+30, y+100, (void *)help_string, 0, 0);
				}
			}
	// 2026-09-03 — simpleInformation paneli tasinabilir (kullanici istegi).
	// Skill butonu slotlari uzerinde degilken ve item tasinmiyorken sol tik
	// drag baslatir. Ekran siniri clamp + kenara yapisma Window::Move'da
	// (statch attr default acik); M_MOVING/M_LEFTBUTTON_UP akisini yukarida
	// cagrilan Window::MouseControl zaten isler.
	switch (message)
	{
	case M_LEFTBUTTON_DOWN:
		if (gpC_mouse_pointer->GetPickUpItem() == NULL &&
			!m_pC_skill->IsPixel2(_x+x, _y+y))
		{
			MoveReady();
			SetOrigin(_x, _y);
		}
		break;
	}

	if(m_pC_skill->IsPixel2(_x+x, _y+y))
		m_pC_skill->MouseControl(message, _x+x, _y+y);

	return true;	
}

void C_VS_UI_TRIBE::Start()
{
	// 2026-09-03 — kaydedilmis panel konumunu geri yukle (minimap
	// paritesi; panel artik tasinabilir, konum UserOption uzerinden
	// SIMPLEINFOMATION_WINDOW slotunda saklanir). Cozunurluk degismis
	// olabilecegi icin ekran ici clamp yapilir.
	// plan F3: mevcut cozunurluk icin per-resolution defter kaydi varsa
	// o ONCELIKLIDIR (legacy slot cozunurluk-bagimsiz tek deger tutar).
	{
		const int resW = g_pUserInformation->iResolution_x;
		const int resH = g_pUserInformation->iResolution_y;

		int px = 0, py = 0;
		if (Phoenix_HudLayout_Get(resW, resH, (int)C_VS_UI_WINDOW_MANAGER::SIMPLEINFOMATION_WINDOW, &px, &py))
		{
			x = px;
			y = py;
		}
		else
		{
			Rect &rect = gpC_vs_ui_window_manager->GetRect(C_VS_UI_WINDOW_MANAGER::SIMPLEINFOMATION_WINDOW);
			if (rect.w != -1)
			{
				x = rect.x;
				y = rect.y;
			}
		}

		if (x < 0) x = 0;
		else if (w < resW && x + w > resW) x = resW - w;
		if (y < 0) y = 0;
		else if (h < resH && y + h > resH) y = resH - h;
	}

	PI_Processor::Start();
	m_pC_chatting->Start();
	gpC_window_manager->AppearWindow(this);

}
void C_VS_UI_TRIBE::Finish()
{	
		// 2026-09-03 — panel konumu persist (tasinabilir panel).
		gpC_vs_ui_window_manager->SetRect(C_VS_UI_WINDOW_MANAGER::SIMPLEINFOMATION_WINDOW, Rect(x, y, w, h));
		// plan F3 — mevcut cozunurlugun defter kaydi da guncellenir
		Phoenix_HudLayout_Set(g_pUserInformation->iResolution_x, g_pUserInformation->iResolution_y,
			(int)C_VS_UI_WINDOW_MANAGER::SIMPLEINFOMATION_WINDOW, x, y);
//		gpC_vs_ui_window_manager->SetAutoHide(C_VS_UI_WINDOW_MANAGER::SIMPLEINFOMATION_WINDOW, (Window::ATTRIBUTES_HIDE )m_bl_hide);
		PI_Processor::Finish();
		gpC_window_manager->DisappearWindow(this);
}

//-----------------------------------------------------------------------------
// C_VS_UI_TRIBE::RelayoutForResolution
//
// 2026-09-03 plan F3 — canli cozunurluk degisiminde HUD relayout.
// Cagiran: UIMessageManager::Execute_UI_APPLY_RESOLUTION (MODE_GAME dali).
// Eski cozunurlugun konumlari deftere yazilir; yeni cozunurluk icin kayit
// varsa uygulanir, yoksa ctor default formulune re-anchor. Her durumda
// ekran ici clamp. Skill butonu minimap follow'u uzerinden tasinir.
//-----------------------------------------------------------------------------
namespace
{
	// Pencereyi tamamen ekran icinde tutar (Window::Move clamp'iyla ayni kural).
	void HudClampToScreen(int& wx, int& wy, int ww, int wh, int resW, int resH)
	{
		if (ww >= resW)          wx = 0;
		else if (wx < 0)         wx = 0;
		else if (wx + ww > resW) wx = resW - ww;
		if (wh >= resH)          wy = 0;
		else if (wy < 0)         wy = 0;
		else if (wy + wh > resH) wy = resH - wh;
	}
}

void C_VS_UI_TRIBE::RelayoutForResolution(int oldW, int oldH)
{
	const int resW = g_pUserInformation->iResolution_x;
	const int resH = g_pUserInformation->iResolution_y;

	// 1. Eski cozunurlugun yerlesimini deftere yaz — kullanici o
	// cozunurluge geri donerse ayni duzeni bulur (kullanici istegi #3).
	if (oldW > 0 && oldH > 0 && (oldW != resW || oldH != resH))
	{
		Phoenix_HudLayout_Set(oldW, oldH, (int)C_VS_UI_WINDOW_MANAGER::SIMPLEINFOMATION_WINDOW, x, y);
		if (m_pC_minimap != NULL)
			Phoenix_HudLayout_Set(oldW, oldH, (int)C_VS_UI_WINDOW_MANAGER::MINIMAP,
				m_pC_minimap->x, m_pC_minimap->y);
		// 2026-09-03 R5 — HPBar / SkillShortcutSlot / BloodBurst da deftere
		if (m_pC_hpbar != NULL)
			Phoenix_HudLayout_Set(oldW, oldH, (int)C_VS_UI_WINDOW_MANAGER::HPBAR,
				m_pC_hpbar->x, m_pC_hpbar->y);
		if (m_pC_ShortCutSlot != NULL)
			Phoenix_HudLayout_Set(oldW, oldH, (int)C_VS_UI_WINDOW_MANAGER::SHORTCUT_SLOT_WINDOW,
				m_pC_ShortCutSlot->x, m_pC_ShortCutSlot->y);
		if (m_pC_BloodBurst != NULL)
			Phoenix_HudLayout_Set(oldW, oldH, (int)C_VS_UI_WINDOW_MANAGER::BLOOD_BURST_WINDOW,
				m_pC_BloodBurst->x, m_pC_BloodBurst->y);
	}

	// 2. simpleInformation: defter kaydi varsa uygula, yoksa default
	// (SetupMenuItems formulu: sol-alt anchor).
	int px = 0, py = 0;
	if (Phoenix_HudLayout_Get(resW, resH, (int)C_VS_UI_WINDOW_MANAGER::SIMPLEINFOMATION_WINDOW, &px, &py))
	{
		x = px;
		y = py;
	}
	else
	{
		x = 0;
		y = resH - h - 2;
	}
	HudClampToScreen(x, y, w, h, resW, resH);
	gpC_vs_ui_window_manager->SetRect(C_VS_UI_WINDOW_MANAGER::SIMPLEINFOMATION_WINDOW, Rect(x, y, w, h));

	// 3. Minimap: defter kaydi varsa uygula, yoksa default (ctor formulu:
	// sag-alt anchor). Skill butonu follow mekanizmasiyla birlikte gider.
	if (m_pC_minimap != NULL)
	{
		if (Phoenix_HudLayout_Get(resW, resH, (int)C_VS_UI_WINDOW_MANAGER::MINIMAP, &px, &py))
		{
			m_pC_minimap->x = px;
			m_pC_minimap->y = py;
		}
		else
		{
			m_pC_minimap->x = resW - m_pC_minimap->w - 2;
			m_pC_minimap->y = resH - m_pC_minimap->h - 2;
		}
		HudClampToScreen(m_pC_minimap->x, m_pC_minimap->y,
			m_pC_minimap->w, m_pC_minimap->h, resW, resH);
		gpC_vs_ui_window_manager->SetRect(C_VS_UI_WINDOW_MANAGER::MINIMAP,
			Rect(m_pC_minimap->x, m_pC_minimap->y, m_pC_minimap->w, m_pC_minimap->h));

		// Skill follow + board flip guncellemesi (drag'deki ayni yol)
		m_pC_minimap->WindowEventReceiver(EVENT_WINDOW_MOVE);
	}

	// 4. (2026-09-03 R5) HPBar / SkillShortcutSlot / BloodBurst: defter
	// kaydi varsa uygula, yoksa ctor default formulu (800x600 tabanli
	// re-center + alt kenar anchor). Uc irk da ayni ctor formullerini
	// kullanir (race parity).
	if (m_pC_hpbar != NULL)
	{
		if (Phoenix_HudLayout_Get(resW, resH, (int)C_VS_UI_WINDOW_MANAGER::HPBAR, &px, &py))
		{
			m_pC_hpbar->x = px;
			m_pC_hpbar->y = py;
		}
		else
		{
			m_pC_hpbar->x = 246 + (resW - 800) / 2;	// ctor formulu
			m_pC_hpbar->y = resH - 105;
		}
		HudClampToScreen(m_pC_hpbar->x, m_pC_hpbar->y, m_pC_hpbar->w, m_pC_hpbar->h, resW, resH);
		gpC_vs_ui_window_manager->SetRect(C_VS_UI_WINDOW_MANAGER::HPBAR,
			Rect(m_pC_hpbar->x, m_pC_hpbar->y, m_pC_hpbar->w, m_pC_hpbar->h));
	}
	if (m_pC_ShortCutSlot != NULL)
	{
		if (Phoenix_HudLayout_Get(resW, resH, (int)C_VS_UI_WINDOW_MANAGER::SHORTCUT_SLOT_WINDOW, &px, &py))
		{
			m_pC_ShortCutSlot->x = px;
			m_pC_ShortCutSlot->y = py;
		}
		else
		{
			m_pC_ShortCutSlot->x = 255 + (resW - 800) / 2;	// ctor formulu
			m_pC_ShortCutSlot->y = resH - 51;
		}
		HudClampToScreen(m_pC_ShortCutSlot->x, m_pC_ShortCutSlot->y,
			m_pC_ShortCutSlot->w, m_pC_ShortCutSlot->h, resW, resH);
		gpC_vs_ui_window_manager->SetRect(C_VS_UI_WINDOW_MANAGER::SHORTCUT_SLOT_WINDOW,
			Rect(m_pC_ShortCutSlot->x, m_pC_ShortCutSlot->y, m_pC_ShortCutSlot->w, m_pC_ShortCutSlot->h));
		// Hide butonu vb. child offset'leri konumdan turetilir
		m_pC_ShortCutSlot->WindowEventReceiver(EVENT_WINDOW_MOVE);
	}
	if (m_pC_BloodBurst != NULL)
	{
		if (Phoenix_HudLayout_Get(resW, resH, (int)C_VS_UI_WINDOW_MANAGER::BLOOD_BURST_WINDOW, &px, &py))
		{
			m_pC_BloodBurst->x = px;
			m_pC_BloodBurst->y = py;
		}
		else
		{
			m_pC_BloodBurst->x = 255 + (resW - 800) / 2;	// ctor formulu
			m_pC_BloodBurst->y = resH - 125;
		}
		HudClampToScreen(m_pC_BloodBurst->x, m_pC_BloodBurst->y,
			m_pC_BloodBurst->w, m_pC_BloodBurst->h, resW, resH);
		gpC_vs_ui_window_manager->SetRect(C_VS_UI_WINDOW_MANAGER::BLOOD_BURST_WINDOW,
			Rect(m_pC_BloodBurst->x, m_pC_BloodBurst->y, m_pC_BloodBurst->w, m_pC_BloodBurst->h));
	}

	CT_Done("HudRelayout: %dx%d -> %dx%d tribe=(%d,%d) minimap=(%d,%d) hpbar=(%d,%d) slot=(%d,%d) burst=(%d,%d)",
		oldW, oldH, resW, resH, x, y,
		m_pC_minimap ? m_pC_minimap->x : -1, m_pC_minimap ? m_pC_minimap->y : -1,
		m_pC_hpbar ? m_pC_hpbar->x : -1, m_pC_hpbar ? m_pC_hpbar->y : -1,
		m_pC_ShortCutSlot ? m_pC_ShortCutSlot->x : -1, m_pC_ShortCutSlot ? m_pC_ShortCutSlot->y : -1,
		m_pC_BloodBurst ? m_pC_BloodBurst->x : -1, m_pC_BloodBurst ? m_pC_BloodBurst->y : -1);
}
