		static DWORD s_lastGearAnomalyAuditTick = 0;
		const DWORD now = timeGetTime();
		const int screenW = (g_pUserInformation != NULL && g_pUserInformation->iResolution_x > 0)
			? g_pUserInformation->iResolution_x
			: 800;
		const int screenH = (g_pUserInformation != NULL && g_pUserInformation->iResolution_y > 0)
			? g_pUserInformation->iResolution_y
			: 600;
		const int gearSize = m_pC_gear_spk != NULL ? m_pC_gear_spk->GetSize() : -1;
		const int gearWindowW = m_pC_gear_spk != NULL ? m_pC_gear_spk->GetWidth(GEAR_WINDOW) : -1;
		const int gearWindowH = m_pC_gear_spk != NULL ? m_pC_gear_spk->GetHeight(GEAR_WINDOW) : -1;
		const int gearWindowInit = (m_pC_gear_spk != NULL && gearSize > GEAR_WINDOW)
			? (int)m_pC_gear_spk->GetSprite(GEAR_WINDOW).IsInit()
			: -1;

		bool anomaly = false;
		const char* reason = "none";
		int badSlot = -1;
		int badSlotX = 0;
		int badSlotY = 0;

		if (m_pC_gear_spk == NULL || gearSize <= GEAR_WINDOW || gearWindowW <= 0 || gearWindowH <= 0 || gearWindowInit != 1)
		{
			anomaly = true;
			reason = "gear_window_sprite";
		}
		else if (w <= 0 || h <= 0 || x < -gearWindowW || y < -gearWindowH || x > screenW + 64 || y > screenH + 64)
		{
			anomaly = true;
			reason = "gear_window_rect";
		}
		else if (m_pC_gear_slot_spk == NULL || m_slot_size <= 0 || m_p_slot_rect == NULL)
		{
			anomaly = true;
			reason = "gear_slot_contract";
		}
		else
		{
			for (int i = 0; i < m_slot_size; ++i)
			{
				const int slotX = x + m_p_slot_rect[i].x;
				const int slotY = y + m_p_slot_rect[i].y;
				if (slotX < -96 || slotY < -96 || slotX > screenW + 96 || slotY > screenH + 96)
				{
					anomaly = true;
					reason = "gear_slot_offscreen";
					badSlot = i;
					badSlotX = slotX;
					badSlotY = slotY;
					break;
				}
			}
		}

		if (anomaly && now - s_lastGearAnomalyAuditTick > 1000)
		{
			Phoenix_VisualAudit_Log("GEAR_ANOMALY",
				"reason=%s race=%d adv=%d other=%d active=%d pos=%d,%d wh=%d,%d screen=%dx%d gearPack=%s gearSize=%d gearWindow=%dx%d init=%d slotPackOk=%d slotSize=%d badSlot=%d badSlotPos=%d,%d focus=%d",
				reason,
				(int)g_eRaceInterface,
				(int)m_bl_Abvencement,
				(int)m_bIsGearOther,
				(int)bActive,
				x, y, w, h,
				screenW, screenH,
				SPK_VAMPIRE_ADVANCEMENTGEAR,
				gearSize,
				gearWindowW,
				gearWindowH,
				gearWindowInit,
				m_pC_gear_slot_spk != NULL ? 1 : 0,
				m_slot_size,
				badSlot,
				badSlotX,
				badSlotY,
				m_focus_slot);
			s_lastGearAnomalyAuditTick = now;
		}
