#if __CONTENTS(__GEAR_SWAP_CHANGE) // C_VS_UI_GEAR::GearChangeButtonShow()
void	C_VS_UI_GEAR::GearChangeButtonShow()
{
	switch(g_pPlayer->GetRace())
	{
	case RACE_SLAYER:
		if ( !m_bIsGearOther )
			m_dwAccepGearID	= g_pSlayerGear->GetAccepGearID();
		else
			m_dwAccepGearID = g_pSlayerGearOther->GetAccepGearID();
		break;

	case RACE_VAMPIRE:
		if ( !m_bIsGearOther )
			m_dwAccepGearID	= g_pVampireGear->GetAccepGearID();
		else
			m_dwAccepGearID = g_pVampireGearOther->GetAccepGearID();
		break;
		
	case RACE_OUSTERS:
		if ( !m_bIsGearOther )
			m_dwAccepGearID	= g_pOustersGear->GetAccepGearID();
		else
			m_dwAccepGearID = g_pOustersGearOther->GetAccepGearID();
		break;
	}

	switch(m_dwAccepGearID)
	{
	case 0:							// ��â���� ��ȣ�� 0�̸� ����â 1�� ��ư ����
		m_pC_gear_spk->BltLocked(x + m_dwGearChange_ID1_Button_Pos_X, y + m_dwGearChange_ID1_Button_Pos_Y, GEAR_BUTTON_SLOT_1_1);
		m_pC_gear_spk->BltLocked(x + m_dwGearChange_ID2_Button_Pos_X, y + m_dwGearChange_ID2_Button_Pos_Y, GEAR_BUTTON_SLOT_2_1);
		break;

	case 1:							// ����â�� ��ȣ�� 1�̸� ����â 2�� ��ư ���� 
		m_pC_gear_spk->BltLocked(x + m_dwGearChange_ID1_Button_Pos_X, y + m_dwGearChange_ID1_Button_Pos_Y, GEAR_BUTTON_SLOT_1_1);
		m_pC_gear_spk->BltLocked(x + m_dwGearChange_ID2_Button_Pos_X, y + m_dwGearChange_ID2_Button_Pos_Y, GEAR_BUTTON_SLOT_2_1);
		break;
	}
}
#endif // __GEAR_SWAP_CHANGE


//-----------------------------------------------------------------------------
// C_VS_UI_GEAR::Start
//
// 
//-----------------------------------------------------------------------------
void C_VS_UI_GEAR::Start(bool bl_set_load)
{
	m_bl_set_load = bl_set_load;
	AttrAlpha(gpC_vs_ui_window_manager->IsAlpha(C_VS_UI_WINDOW_MANAGER::GEAR));
	if(bl_set_load == true)
	{
		Rect &rect = gpC_vs_ui_window_manager->GetRect(C_VS_UI_WINDOW_MANAGER::GEAR);
		if(rect.w != -1)
		{
			x = rect.x;
			y = rect.y;
		}
	}
	
	PI_Processor::Start();
	
	AttrPin(true);
	gpC_window_manager->AppearWindow(this);

	if (Phoenix_VisualAudit_IsEnabled())
	{
		const char* slotPackName = "unknown";
		switch(g_eRaceInterface)
		{
		case RACE_VAMPIRE:
			slotPackName = SPK_VAMPIRE_GEAR_SLOT;
			break;
		case RACE_SLAYER:
			slotPackName = SPK_SLAYER_GEAR_SLOT;
			break;
		case RACE_OUSTERS:
			slotPackName = SPK_OUSTERS_GEAR_SLOT;
			break;
		}

		const int gearSize = m_pC_gear_spk != NULL ? m_pC_gear_spk->GetSize() : -1;
		const int gearWindowW = m_pC_gear_spk != NULL ? m_pC_gear_spk->GetWidth(GEAR_WINDOW) : -1;
		const int gearWindowH = m_pC_gear_spk != NULL ? m_pC_gear_spk->GetHeight(GEAR_WINDOW) : -1;
		const int gearWindowInit = (m_pC_gear_spk != NULL && gearSize > GEAR_WINDOW)
			? (int)m_pC_gear_spk->GetSprite(GEAR_WINDOW).IsInit()
			: -1;

		Phoenix_VisualAudit_Log("GEAR_START",
			"race=%d adv=%d other=%d setLoad=%d pos=%d,%d wh=%d,%d gearPack=%s gearSize=%d gearWindow=%dx%d init=%d slotPack=%s slotPackOk=%d slotSize=%d",
			(int)g_eRaceInterface,
			(int)m_bl_Abvencement,
			(int)m_bIsGearOther,
			(int)bl_set_load,
			x, y, w, h,
			SPK_VAMPIRE_ADVANCEMENTGEAR,
			gearSize,
			gearWindowW,
			gearWindowH,
			gearWindowInit,
			slotPackName,
			m_pC_gear_slot_spk != NULL ? 1 : 0,
			m_slot_size);
	}
	
	//	m_bl_close_button_focused = false;
	//	m_bl_close_button_pushed = false;
	//	m_bl_help_button_focused = false;
	//	m_bl_help_button_pushed = false;
}

//-----------------------------------------------------------------------------
// C_VS_UI_GEAR::Finish
//
// 
//-----------------------------------------------------------------------------
void C_VS_UI_GEAR::Finish()
{
	gpC_vs_ui_window_manager->SetAlpha(C_VS_UI_WINDOW_MANAGER::GEAR, GetAttributes()->alpha);
	if(m_bl_set_load)
	{
		gpC_vs_ui_window_manager->SetRect(C_VS_UI_WINDOW_MANAGER::GEAR, Rect(x, y, w, h));
	}
	
	PI_Processor::Finish();
	
	gpC_window_manager->DisappearWindow(this);
}

