/*-----------------------------------------------------------------------------
- ResetScroll
- 
-----------------------------------------------------------------------------*/
void C_VS_UI_CHATTING::ResetScroll()
{
	
	m_pC_scroll_bar->SetSize(Rect(w-23, 35, -1, h-79));	

	int i=0, line = 0;
	C_VS_UI_CHAT_LINE * p_line;	
	while(p_line = m_pC_history_list.GetLine(i))
	{
		i++;
		const int _ID_GAP = 2;

		const int conditionIndex = static_cast<int>(p_line->GetCondition());
		if(conditionIndex >= 0 && conditionIndex < CLD_TOTAL && m_chat_filter[conditionIndex] == false)
			continue;

		int vx = CHAT_LINE_START_X;
		
		char* p_temp = NULL;
		if(p_temp = (char*)p_line->GetMsgString())
		{
			int	cut_length = CHAT_WINDOW_WIDTH/g_GetStringWidth("F", gpC_base->m_chatting_pi.hfont)
							- (p_line->GetIdString() == NULL ? 0 : (strlen(p_line->GetIdString())+2));

			int str_length = strlen(p_temp);
			int loopSum = cut_length;
			
			if(cut_length < str_length)
			{					
				for(;;)
				{					
					int len = cut_length;
					
					if(!g_PossibleStringCut(p_temp, loopSum))
					{
						--loopSum;
						--len;
					}
					
					++line;
					
					if(cut_length >= str_length - loopSum)
						break;
					
					loopSum += cut_length;
				}
			}
			
			++line;
		}
	}


	m_pC_scroll_bar->SetPosMax(line-g_HISTORY_LINE+1);
	m_pC_scroll_bar->SetScrollPos(0);
	InvalidateChatHistoryCache();
}

void C_VS_UI_CHATTING::InvalidateChatHistoryCache()
{
	m_chatHistoryCacheDirty = true;
}

bool C_VS_UI_CHATTING::EnsureChatHistoryCacheSurface(int width, int height)
{
	if(width <= 0 || height <= 0)
		return false;

	if(m_hChatHistoryCacheDC != NULL &&
		m_hChatHistoryCacheBitmap != NULL &&
		m_pChatHistoryCacheBits != NULL &&
		m_chatHistoryCacheWidth == width &&
		m_chatHistoryCacheHeight == height)
	{
		return true;
	}

	ReleaseChatHistoryCache();

	m_hChatHistoryCacheDC = CreateCompatibleDC(NULL);
	if(m_hChatHistoryCacheDC == NULL)
		return false;

	struct RGB565BitmapInfo
	{
		BITMAPINFOHEADER header;
		DWORD masks[3];
	};

	RGB565BitmapInfo bitmapInfo;
	ZeroMemory(&bitmapInfo, sizeof(bitmapInfo));
	bitmapInfo.header.biSize = sizeof(BITMAPINFOHEADER);
	bitmapInfo.header.biWidth = width;
	bitmapInfo.header.biHeight = -height;
	bitmapInfo.header.biPlanes = 1;
	bitmapInfo.header.biBitCount = 16;
	bitmapInfo.header.biCompression = BI_BITFIELDS;
	bitmapInfo.masks[0] = 0xF800;
	bitmapInfo.masks[1] = 0x07E0;
	bitmapInfo.masks[2] = 0x001F;

	void *bits = NULL;
	m_hChatHistoryCacheBitmap = CreateDIBSection(NULL, reinterpret_cast<BITMAPINFO*>(&bitmapInfo), DIB_RGB_COLORS, &bits, NULL, 0);
	if(m_hChatHistoryCacheBitmap == NULL || bits == NULL)
	{
		ReleaseChatHistoryCache();
		return false;
	}

	m_hChatHistoryCacheOldBitmap = static_cast<HBITMAP>(SelectObject(m_hChatHistoryCacheDC, m_hChatHistoryCacheBitmap));
	m_pChatHistoryCacheBits = static_cast<WORD*>(bits);
	m_chatHistoryCacheWidth = width;
	m_chatHistoryCacheHeight = height;
	m_chatHistoryCachePitchWords = (((width * 16 + 31) / 32) * 4) / sizeof(WORD);
	m_chatHistoryCacheValid = false;
	m_chatHistoryCacheDirty = true;
	return true;
}

void C_VS_UI_CHATTING::ReleaseChatHistoryCache()
{
	if(m_hChatHistoryCacheDC != NULL && m_hChatHistoryCacheOldBitmap != NULL)
	{
		SelectObject(m_hChatHistoryCacheDC, m_hChatHistoryCacheOldBitmap);
		m_hChatHistoryCacheOldBitmap = NULL;
	}

	if(m_hChatHistoryCacheBitmap != NULL)
	{
		DeleteObject(m_hChatHistoryCacheBitmap);
		m_hChatHistoryCacheBitmap = NULL;
	}

	if(m_hChatHistoryCacheDC != NULL)
	{
		DeleteDC(m_hChatHistoryCacheDC);
		m_hChatHistoryCacheDC = NULL;
	}

	m_pChatHistoryCacheBits = NULL;
	m_chatHistoryCacheWidth = 0;
	m_chatHistoryCacheHeight = 0;
	m_chatHistoryCachePitchWords = 0;
	m_chatHistoryCacheValid = false;
	m_chatHistoryCacheDirty = true;
}

bool C_VS_UI_CHATTING::BuildChatHistoryCache()
{
	if(m_pC_scroll_bar == NULL || gpC_base == NULL)
		return false;

	const int cacheLeft = CHAT_LINE_START_X - 70;
	const int cacheTop = CHAT_HISTORY_START_Y - (FONT_GAP * (g_HISTORY_LINE - 1));
	const int cacheWidth = max(64, w - (cacheLeft - x));
	const int cacheHeight = max(FONT_GAP, FONT_GAP * g_HISTORY_LINE + FONT_GAP);
	const int scrollPos = m_pC_scroll_bar->GetScrollPos();
	const int historySize = m_pC_history_list.Size();
	const int filterMask = Phoenix_GetChatFilterMask(m_chat_filter);

	if(m_chatHistoryCacheValid &&
		!m_chatHistoryCacheDirty &&
		m_chatHistoryCacheLeft == cacheLeft &&
		m_chatHistoryCacheTop == cacheTop &&
		m_chatHistoryCacheWidth == cacheWidth &&
		m_chatHistoryCacheHeight == cacheHeight &&
		m_chatHistoryCacheScrollPos == scrollPos &&
		m_chatHistoryCacheHistorySize == historySize &&
		m_chatHistoryCacheFilterMask == filterMask &&
		m_chatHistoryCacheUserFont == gpC_base->m_user_id_pi.hfont &&
		m_chatHistoryCacheChatFont == gpC_base->m_chatting_pi.hfont)
	{
		return true;
	}

	if(!EnsureChatHistoryCacheSurface(cacheWidth, cacheHeight))
		return false;

	Phoenix_FillChatHistoryCache(m_pChatHistoryCacheBits, m_chatHistoryCachePitchWords, m_chatHistoryCacheWidth, m_chatHistoryCacheHeight);

	const int _ID_GAP = 2;
	int line = 0;
	for(int i = 0, scroll = 0;
		i < m_pC_history_list.Size() && line < g_HISTORY_LINE;
		++i)
	{
		C_VS_UI_CHAT_LINE *p_line = m_pC_history_list.GetLine(i);
		if(p_line == NULL)
			continue;

		const int conditionIndex = static_cast<int>(p_line->GetCondition());
		if(conditionIndex >= 0 && conditionIndex < CLD_TOTAL && m_chat_filter[conditionIndex] == false)
			continue;

		if(p_line->GetMsgString() == NULL)
			continue;

		const char *p_temp = p_line->GetMsgString();
		const char *chatIdDivisor = Phoenix_GetChatIdDivisor(p_line->GetCondition());
		p_line->PrepareRenderCache(CHAT_WINDOW_WIDTH, _ID_GAP, chatIdDivisor, gpC_base->m_user_id_pi.hfont, gpC_base->m_chatting_pi.hfont);

		int vx = CHAT_LINE_START_X - 70;
		vx += p_line->GetCachedIdWidth();
		vx += p_line->GetCachedDivisorWidth();
		vx += _ID_GAP;

		const std::vector<int> &CutLenghtVec = p_line->GetCachedCutLengths();
		if(CutLenghtVec.empty())
			continue;

		int loopCnt = static_cast<int>(CutLenghtVec.size()) - 1;
		const char *pDrawStr = p_temp + p_line->GetCachedMessageLength();

		for(;
			line < g_HISTORY_LINE && line >= 0 && loopCnt >= 0;
			--loopCnt, ++line)
		{
			PrintInfo *pi = (p_line->GetCondition() == CLD_ZONECHAT) ? &gpC_base->m_user_id_pi : &gpC_base->m_chatting_pi;

			if(scroll < scrollPos)
			{
				++scroll;
				--line;
				if(scroll <= scrollPos)
					continue;
			}

			int curr_length = CutLenghtVec[loopCnt];
			pDrawStr -= curr_length;

			const int drawY = CHAT_HISTORY_START_Y - (FONT_GAP * line);
			int localX = vx - cacheLeft;
			const int localY = drawY - cacheTop;

			if(loopCnt == 0 && p_line->GetIdString())
			{
				int tabvalue = 0;
				if(strstr(p_line->GetIdString(), (*g_pGameStringTable)[UI_STRING_MESSAGE_MASTER_NAME].GetString()) != NULL)
					tabvalue = CLD_MASTER;
				else
					tabvalue = p_line->GetCondition();

				localX = Phoenix_DrawCachedTaggedText(m_hChatHistoryCacheDC, (CHAT_LINE_START_X - 70) - cacheLeft, localY,
					p_line->GetIdString(), gpC_base->m_user_id_pi, m_color_tab[tabvalue]);
				localX = Phoenix_DrawCachedTaggedText(m_hChatHistoryCacheDC, localX, localY,
					chatIdDivisor, gpC_base->m_chatting_pi, m_color_tab[tabvalue]);
				localX += _ID_GAP;
			}

			Phoenix_DrawCachedTaggedTextLen(m_hChatHistoryCacheDC, localX, localY,
				pDrawStr, curr_length, *pi, p_line->GetColor());
		}
	}

	m_chatHistoryCacheLeft = cacheLeft;
	m_chatHistoryCacheTop = cacheTop;
	m_chatHistoryCacheScrollPos = scrollPos;
	m_chatHistoryCacheHistorySize = historySize;
	m_chatHistoryCacheFilterMask = filterMask;
	m_chatHistoryCacheUserFont = gpC_base->m_user_id_pi.hfont;
	m_chatHistoryCacheChatFont = gpC_base->m_chatting_pi.hfont;
	m_chatHistoryCacheValid = true;
	m_chatHistoryCacheDirty = false;
	return true;
}

bool C_VS_UI_CHATTING::BltChatHistoryCache()
{
	if(!m_chatHistoryCacheValid || m_pChatHistoryCacheBits == NULL || gpC_base == NULL || gpC_base->m_p_DDSurface_back == NULL)
		return false;

	CDirectDrawSurface *backSurface = gpC_base->m_p_DDSurface_back;
	if(!backSurface->Lock())
		return false;

	WORD *destBase = static_cast<WORD*>(backSurface->GetSurfacePointer());
	const int destPitchWords = static_cast<int>(backSurface->GetSurfacePitch() / sizeof(WORD));
	const int destWidth = backSurface->GetWidth();
	const int destHeight = backSurface->GetHeight();

	if(destBase == NULL || destPitchWords <= 0 || destWidth <= 0 || destHeight <= 0)
	{
		backSurface->Unlock();
		return false;
	}

	int sourceX = 0;
	int sourceY = 0;
	int destX = m_chatHistoryCacheLeft;
	int destY = m_chatHistoryCacheTop;
	int copyWidth = m_chatHistoryCacheWidth;
	int copyHeight = m_chatHistoryCacheHeight;

	if(destX < 0)
	{
		sourceX = -destX;
		copyWidth += destX;
		destX = 0;
	}
	if(destY < 0)
	{
		sourceY = -destY;
		copyHeight += destY;
		destY = 0;
	}
	if(destX + copyWidth > destWidth)
		copyWidth = destWidth - destX;
	if(destY + copyHeight > destHeight)
		copyHeight = destHeight - destY;

	if(copyWidth <= 0 || copyHeight <= 0)
	{
		backSurface->Unlock();
		return true;
	}

	for(int row = 0; row < copyHeight; ++row)
	{
		const WORD *src = m_pChatHistoryCacheBits + (sourceY + row) * m_chatHistoryCachePitchWords + sourceX;
		WORD *dst = destBase + (destY + row) * destPitchWords + destX;
		for(int col = 0; col < copyWidth; ++col)
		{
			const WORD pixel = src[col];
			if(pixel != PHOENIX_CHAT_HISTORY_CACHE_KEY)
				dst[col] = pixel;
		}
	}

	// Faz G5 (2026-09-01) — dx11gpu: ham colorkey blit komut katmanina dirty
	// bildirilir (z-order icin checkpoint segment tetikler)
	{
		phoenix::render::D3D11SpriteCommands& cmds =
			phoenix::render::D3D11SpriteCommands::Instance();
		if(cmds.IsActive() && cmds.IsCompositionTarget(destBase))
		{
			RECT dirty;
			dirty.left   = destX;
			dirty.top    = destY;
			dirty.right  = destX + copyWidth;
			dirty.bottom = destY + copyHeight;
			cmds.MarkDirty(&dirty);
		}
	}

	backSurface->Unlock();
	return true;
}

