	int line = 0;

	{
		Phoenix_FrameProbeStageScope fpChatHistoryDraw("Chat.Show.HistoryDraw", g_hWnd, (int)g_bActiveApp, (int)g_bActiveGame);
		for(int i = 0, scroll = 0;
			i < m_pC_history_list.Size() && line < g_HISTORY_LINE; /*++line,*/ ++i)
		{
			C_VS_UI_CHAT_LINE * p_line;
			p_line = m_pC_history_list.GetLine(i);
			const int _ID_GAP = 2;

			if(p_line)
			{
				const int conditionIndex = static_cast<int>(p_line->GetCondition());
				if(conditionIndex >= 0 && conditionIndex < CLD_TOTAL && m_chat_filter[conditionIndex] == false)
				{
					/*--line;*/
					continue;
				}

				if (p_line->GetMsgString())
				{
					const char *p_temp = p_line->GetMsgString();
					const char *chatIdDivisor = Phoenix_GetChatIdDivisor(p_line->GetCondition());
					p_line->PrepareRenderCache(CHAT_WINDOW_WIDTH, _ID_GAP, chatIdDivisor, gpC_base->m_user_id_pi.hfont, gpC_base->m_chatting_pi.hfont);

					int vx = CHAT_LINE_START_X-70;
					vx += p_line->GetCachedIdWidth();
					vx += p_line->GetCachedDivisorWidth();
					vx += _ID_GAP;

					const std::vector<int> & CutLenghtVec = p_line->GetCachedCutLengths();
					if(CutLenghtVec.empty())
						continue;

					int	loopCnt	= CutLenghtVec.size() - 1;

					const char* pDrawStr	= p_temp + p_line->GetCachedMessageLength();

					for(;
						line < g_HISTORY_LINE && line >= 0 && loopCnt >= 0;
						--loopCnt, ++line)
					{
						PrintInfo* pi;

						if (p_line->GetCondition() == CLD_ZONECHAT)
							pi = &gpC_base->m_user_id_pi;
						else
							pi = &gpC_base->m_chatting_pi;


						if(scroll < m_pC_scroll_bar->GetScrollPos())
						{
							++scroll;
							--line;
							if(scroll <= m_pC_scroll_bar->GetScrollPos())
								continue;
						}

						int curr_length = CutLenghtVec[loopCnt];

						pDrawStr -= curr_length;

						if (loopCnt == 0 && p_line->GetIdString())
						{
							int tabvalue=0;
							if(strstr(p_line->GetIdString(), (*g_pGameStringTable)[UI_STRING_MESSAGE_MASTER_NAME].GetString()) != NULL)
								tabvalue=CLD_MASTER;
							else
								tabvalue=p_line->GetCondition();

							vx = g_PrintColorStr(CHAT_LINE_START_X-70, CHAT_HISTORY_START_Y-(FONT_GAP*line), p_line->GetIdString(), gpC_base->m_user_id_pi, m_color_tab[tabvalue]);
							vx = g_PrintColorStr(vx, CHAT_HISTORY_START_Y-(FONT_GAP*line), chatIdDivisor, gpC_base->m_chatting_pi, m_color_tab[tabvalue]);
							vx += _ID_GAP;
						}

						g_PrintColorStrLenNoMeasure(vx, CHAT_HISTORY_START_Y - (FONT_GAP * line),
							pDrawStr, curr_length, *pi, p_line->GetColor());
					}
				}
			}
		}
	}
