				int int_cur = g_char_slot_ingame.INT_CUR;
				
				int sum = str_cur+dex_cur+int_cur;
				reqSUM = SafeReqSUM(pMouseItem->GetItemClass(), pMouseItem->GetItemType());
				
				b_item_NetCapacity = (sum<reqSUM);
