	// FAZ 4 (2026-05-03): hardcoded x=255 (800x600 odaklı shortcut slot row) → res-aware center.
	Set(255 + (g_pUserInformation->iResolution_x - 800)/2, g_pUserInformation->iResolution_y-51, m_slot_width*(C_VS_UI_SKILL::HOTKEY_MAX), m_pC_shortcut_slot_spk->GetHeight(SLOT_BOX)+9);

	m_pC_button_group = new ButtonGroup(this);
