//
// 
//-----------------------------------------------------------------------------
C_VS_UI_SHORTCUT_SLOT::~C_VS_UI_SHORTCUT_SLOT()
{
	gpC_vs_ui_window_manager->SetRect(C_VS_UI_WINDOW_MANAGER::SHORTCUT_SLOT_WINDOW, Rect(x, y, w, h));
	gpC_vs_ui_window_manager->SetAutoHide(C_VS_UI_WINDOW_MANAGER::SHORTCUT_SLOT_WINDOW, (Window::ATTRIBUTES_HIDE )m_bl_slot_hide);

	g_UnregisterWindow(this);

	if(m_pC_shortcut_slot_spk)
	{
		DeleteNew(m_pC_shortcut_slot_spk);
		m_pC_shortcut_slot_spk = NULL;
	}

	DeleteNew(m_pC_button_group);
}

int C_VS_UI_SHORTCUT_SLOT::GetDelay(int id) const
{
	if((*g_pSkillInfoTable)[id].GetDelayTime() == 0)return 0;	
	int DelayTime = (*g_pSkillInfoTable)[id].GetDelayTime();
	if( id == SKILL_WILL_OF_LIFE )
		DelayTime = (3+ (g_char_slot_ingame.level/10))*2*1000;

	return (*g_pSkillInfoTable)[id].GetAvailableTimeLeft()*100/DelayTime;
}

int C_VS_UI_SHORTCUT_SLOT::GetActiveHotkeySkillId(int hk) const
{
	const int selectedSkillId = gC_vs_ui.GetSelectedSkillID();
	if (selectedSkillId != NOT_SELECTED)
	{
		for (int hl = 0; hl < C_VS_UI_SKILL::GRADE_MAX; hl++)
		{
			if (gC_vs_ui.GetHotkey((C_VS_UI_SKILL::HOTKEY)hk,
			                       (C_VS_UI_SKILL::HOTKEY_GRADE)hl) == selectedSkillId)
				return selectedSkillId;
		}
	}

	return gC_vs_ui.GetHotkey((C_VS_UI_SKILL::HOTKEY)hk, (C_VS_UI_SKILL::HOTKEY_GRADE)0);
}

void C_VS_UI_SHORTCUT_SLOT::DrawSkillCooldownText(POINT ptPos, int skillid) const
{
	if (skillid == NOT_SELECTED || skillid < 0)
		return;
	if ((*g_pSkillInfoTable)[skillid].GetDelayTime() == 0)
		return;

	const DWORD leftMs = (*g_pSkillInfoTable)[skillid].GetAvailableTimeLeft();
	if (leftMs == 0)
		return;

	char cooldownText[16];
	sprintf(cooldownText, "%.1f", leftMs / 1000.0f);

	SPRITE_ID spr_id = (*g_pSkillInfoTable)[skillid].GetSpriteID();
	CSprite *p_sprite = &C_VS_UI_SKILL::m_C_spk_mini_new[spr_id];
	if (p_sprite == NULL)
		return;

	const int textW = g_GetStringWidth(cooldownText, gpC_base->m_item_desc_pi.hfont);
	const int textH = g_GetStringHeight(cooldownText, gpC_base->m_item_desc_pi.hfont);
	const int drawX = ptPos.x + (p_sprite->GetWidth() - textW) / 2;
	const int drawY = ptPos.y + (p_sprite->GetHeight() - textH) / 2;

	// Okunabilirlik: siyah outline + parlak metin (floating damage ile ayni pattern)
	g_PrintColorStrOut(drawX, drawY, cooldownText, gpC_base->m_item_desc_pi,
	                   RGB(255, 255, 255), RGB(0, 0, 0));
}

void C_VS_UI_SHORTCUT_SLOT::_DrawSkillCooldownText(int hk)
{
	const int activeSkillId = GetActiveHotkeySkillId(hk);
	if (activeSkillId != NOT_SELECTED && activeSkillId >= 0)
	{
		POINT iconPos;
		iconPos.x = x + (hk * m_slot_width) + 2;
		iconPos.y = y + 3;
		DrawSkillCooldownText(iconPos, activeSkillId);
	}

	// Hover: yukari acilan diger 3 skill icin de CD sayaci
	if (m_focused_slot != hk)
		return;

	int low_skill_y = 0;
	for (int hl = 0; hl < C_VS_UI_SKILL::GRADE_MAX; hl++)
	{
		const int skillid = gC_vs_ui.GetHotkey((C_VS_UI_SKILL::HOTKEY)hk,
		                                       (C_VS_UI_SKILL::HOTKEY_GRADE)hl);
		if (skillid == -1 || skillid == NOT_SELECTED || skillid == activeSkillId)
			continue;

		low_skill_y += 37;
		POINT iconPos;
		iconPos.x = x + (hk * m_slot_width) + 2;
		iconPos.y = y - low_skill_y - 5;
		DrawSkillCooldownText(iconPos, skillid);
	}
}

