void C_VS_UI_SHORTCUT_SLOT::Process()
{
	ProcessHide();

	m_pC_button_group->Process();
}

void C_VS_UI_SHORTCUT_SLOT::Start()
{
	Rect &rect = gpC_vs_ui_window_manager->GetRect(C_VS_UI_WINDOW_MANAGER::SHORTCUT_SLOT_WINDOW);
	//if(m_width_mode == gpC_vs_ui_window_manager->IsBloodBurstHeight())	Run(BLOODBURST_CHANGE_ID);
	if(rect.w != -1)
	{
		x = rect.x;
		y = rect.y;
	}	

	// 2026-09-03 R5 — per-resolution defter oncelikli (UserOption.set
	// rect'i cozunurluk bilgisi tasimiyor; defter kaydi varsa onu kullan)
	{
		int px = 0, py = 0;
		if (Phoenix_HudLayout_Get(g_pUserInformation->iResolution_x,
			g_pUserInformation->iResolution_y,
			(int)C_VS_UI_WINDOW_MANAGER::SHORTCUT_SLOT_WINDOW, &px, &py))
		{
			x = px;
			y = py;
		}
	}

	PI_Processor::Start();
	m_pC_button_group->Init();
	m_bl_slot_hide = false;gpC_vs_ui_window_manager->GetAutoHide(C_VS_UI_WINDOW_MANAGER::SHORTCUT_SLOT_WINDOW)>0;

	WindowEventReceiver(EVENT_WINDOW_MOVE);
	gpC_window_manager->AppearWindow(this);
}

void C_VS_UI_SHORTCUT_SLOT::Finish()
{
	gpC_vs_ui_window_manager->SetRect(C_VS_UI_WINDOW_MANAGER::SHORTCUT_SLOT_WINDOW, Rect(x, y, w, h));
	// 2026-09-03 R5 — mevcut cozunurlugun defter kaydi da guncellenir
	Phoenix_HudLayout_Set(g_pUserInformation->iResolution_x, g_pUserInformation->iResolution_y,
		(int)C_VS_UI_WINDOW_MANAGER::SHORTCUT_SLOT_WINDOW, x, y);
	gpC_vs_ui_window_manager->SetAutoHide(C_VS_UI_WINDOW_MANAGER::SHORTCUT_SLOT_WINDOW, (Window::ATTRIBUTES_HIDE )m_bl_slot_hide);

	PI_Processor::Finish();

	gpC_window_manager->DisappearWindow(this);
}

