void C_VS_UI_SHORTCUT_SLOT::Show()
{
	CT_Done("WnSh: C_VS_UI_SHORTCUT_SLOT::Show ENTER pthis=%p", (void*)this);
	if (gpC_base->m_p_DDSurface_back->Lock())
	{
		if (!m_bl_slot_hide) // hide ���°� �ƴϾ�� �Ѵ�.
		{
			for (int hk=0; hk < C_VS_UI_SKILL::HOTKEY_MAX; hk++)
			{
				m_pC_shortcut_slot_spk->BltLocked(x+(hk*m_slot_width), y, SLOT_BOX);
			}

			for (int hk=0; hk < C_VS_UI_SKILL::HOTKEY_MAX; hk++)
			{
				switch (g_eRaceInterface)
				{
				case RACE_VAMPIRE :
					{
						if (hk < 2)
						{
							const MItem* p_item = NULL;
							if (hk == 0)
							{
								p_item = Vampire_SerumF1();
							}
							else if (hk == 1)
							{ 
								p_item = Vampire_SerumF2();
							}	

							if (p_item != NULL)
							{
								gpC_item->BltLocked(x+m_slot_width/2+(hk*m_slot_width)-gpC_item->GetWidth(p_item->GetInventoryFrameID())/2, 
									y+m_slot_width/2-gpC_item->GetHeight(p_item->GetInventoryFrameID())/2, p_item->GetInventoryFrameID());
							}
						}
						else
						{
							_DrawSkillIcon(hk); // ��ų ���
						}
					}
				default :
					{
						int HotKey_Type = gC_vs_ui.GetHotkeyType((C_VS_UI_SKILL::HOTKEY)hk);
						switch (HotKey_Type)
						{
						case C_VS_UI_TRIBE::QUICKITEM_TYPE :
							{
								const MItem * p_item = NULL;
								if (g_eRaceInterface == RACE_OUSTERS)
								{
									int slot = gC_vs_ui.GetQuikSlot((C_VS_UI_OUSTERS_QUICKITEM::HOTKEY)hk);

									if (slot != -1)
									{
										p_item = C_VS_UI_OUSTERS_QUICKITEM::GetItem(slot);
									}
								}
								else
								{
									if (g_pQuickSlot != NULL)
									{
										int slot = gC_vs_ui.GetQuikSlot((C_VS_UI_SLAYER_QUICKITEM::HOTKEY)hk);

										if (slot != -1)
										{
											p_item = g_pQuickSlot->GetItem(slot);
										}
									}
								}

								if (p_item != NULL)
								{
									gpC_item->BltLocked(x+m_slot_width/2+(hk*m_slot_width)-gpC_item->GetWidth(p_item->GetInventoryFrameID())/2, 
										y+m_slot_width/2-gpC_item->GetHeight(p_item->GetInventoryFrameID())/2, p_item->GetInventoryFrameID());
								}
							}
							break;
						case C_VS_UI_TRIBE::SKILL_TYPE:
							{
								_DrawSkillIcon(hk); // ��ų ���
							}
							break;
						}
					}
					break;
				}

				m_pC_shortcut_slot_spk->BltLocked(x+6+(hk*m_slot_width), y+60-25, HOTKEY_BOX);
			}
		}
		m_pC_button_group->Show();
		gpC_base->m_p_DDSurface_back->Unlock();
	}


	g_FL2_GetDC();

	if (!m_bl_slot_hide) // hide ���°� �ƴϾ�� �Ѵ�.
	{
		for (int hk=0; hk < C_VS_UI_SKILL::HOTKEY_MAX; hk++)
		{
			switch (g_eRaceInterface)
			{
			case RACE_VAMPIRE :
				{
					if (hk < 2)
					{
						const MItem* p_item = NULL;
						if (hk == 0)
						{ 
							p_item = Vampire_SerumF1();
						}
						else if (hk == 1) 
						{
							p_item = Vampire_SerumF2();
						}	

						if (p_item != NULL)
						{
							char tmp_str[4];
							sprintf(tmp_str, "%d", p_item->GetNumber());
							g_PrintColorStr(x+28+(hk*m_slot_width), y+23, tmp_str, gpC_base->m_item_desc_pi,  RGB(220, 220, 220));

							sprintf(tmp_str, "F%d", hk+1);
							g_PrintColorStr(x+14+(hk*m_slot_width), y+37, tmp_str, gpC_base->m_item_desc_pi, RGB(140, 140, 255));
						}
					}
					else
					{
						_DrawSkillHotKey(hk);  // ��Ű ���
						_DrawSkillCooldownText(hk);
					}
				}
			default:
				{
					int HotKey_Type = gC_vs_ui.GetHotkeyType((C_VS_UI_SKILL::HOTKEY)hk);
					switch (HotKey_Type)
					{
					case C_VS_UI_TRIBE::QUICKITEM_TYPE :
						{
							const MItem * p_item = NULL;
							if (g_eRaceInterface == RACE_OUSTERS)
							{
								int slot = gC_vs_ui.GetQuikSlot((C_VS_UI_OUSTERS_QUICKITEM::HOTKEY)hk);
								if (slot != -1)
								{
									p_item = C_VS_UI_OUSTERS_QUICKITEM::GetItem(slot);
								}
							}
							else
							{
								if (g_pQuickSlot != NULL)
								{
									int slot = gC_vs_ui.GetQuikSlot((C_VS_UI_SLAYER_QUICKITEM::HOTKEY)hk);
									if (slot != -1)
									{
										p_item = g_pQuickSlot->GetItem(slot);
									}
								}
							}

							if (p_item != NULL)
							{
								char tmp_str[4];
								sprintf(tmp_str, "%d", p_item->GetNumber());
								g_PrintColorStr(x+28+(hk*m_slot_width), y+23, tmp_str, gpC_base->m_item_desc_pi,  RGB(220, 220, 220));

								sprintf(tmp_str, "F%d", hk+1);
								g_PrintColorStr(x+14+(hk*m_slot_width), y+37, tmp_str, gpC_base->m_item_desc_pi, RGB(140, 140, 255));
							}
						}
						break;

					case C_VS_UI_TRIBE::SKILL_TYPE :
						{
							_DrawSkillHotKey(hk); // ��Ű ���
							_DrawSkillCooldownText(hk);
						}
						break;
					}
				}
				break;
			}
		}
	}
	if (m_focused_slot != -1)
	{
		m_focused_slot = -1;
	}
	m_pC_button_group->ShowDescription();
	g_FL2_ReleaseDC();
}

//-----------------------------------------------------------------------------
// MouseControl
//
// 
//-----------------------------------------------------------------------------
bool C_VS_UI_SHORTCUT_SLOT::MouseControl(UINT message, int _x, int _y)
{
	Window::MouseControl(message, _x, _y);
	_x-=x; _y-=y;
	//������
	m_pC_button_group->MouseControl(message, _x, _y);

	int i;


	switch (message)
	{
	case M_MOVING:
		{
			/*
			if(_x >= 5 && _x < 5+10*20 && _y >= 5 && _y < 5+20)
			{
			select = (_x-5)/20+m_scroll;
			}
			*/
			for (int i=0; i<12; i++)
			{
				if (_x >= i*m_slot_width && _x < (i+1)*m_slot_width)
				{
					m_focused_slot = i;
					break;
				}
			}
			/*
			int skillid;
			for (int i=0; i<3; i++)
			{
			skillid = gC_vs_ui.GetHotkey((C_VS_UI_SKILL::HOTKEY)m_focused_slot, (C_VS_UI_SKILL::HOTKEY_GRADE)i);
			if (skillid != -1)
			{
			//char buf[10];
			//sprintf(buf, "%d", skillid);
			//MessageBox(NULL, buf,MB_OK,NULL);
			g_descriptor_manager.Set(DID_SKILL, x+150, y, NULL, skillid, 0);
			}
			}
			*/
		}

		break;

	case M_LEFTBUTTON_DOWN:
	case M_LB_DOUBLECLICK:
		if (gpC_mouse_pointer->GetPickUpItem() == false && m_bl_slot_hide == false) //&& re)
		{
			MoveReady();
			SetOrigin(_x, _y);
			break;
		}
		break;
	}


	return true;
	//return true;
}

