//-----------------------------------------------------------------------------
// Run
//
// 
//-----------------------------------------------------------------------------
void C_VS_UI_SHORTCUT_SLOT::Run(id_t id)
{
	m_bl_slot_hide = !m_bl_slot_hide;

	if (m_bl_slot_hide)
	{
		w = m_pC_shortcut_slot_spk->GetWidth(BUTTON_HIDE);
		h = m_pC_shortcut_slot_spk->GetHeight(BUTTON_HIDE);
	}
	else
	{
		w = m_slot_width*(C_VS_UI_SKILL::HOTKEY_MAX);
		h = m_pC_shortcut_slot_spk->GetHeight(SLOT_BOX);
	}
}

