void	C_VS_UI_REQUEST_PARTY::Start()
{
	PI_Processor::Start();
	
	gpC_window_manager->AppearWindow(this);
	
	m_bl_pushed = false;
	m_bl_focused = false;
}

//-----------------------------------------------------------------------------
// C_VS_UI_REQUEST_PARTY::Finish
//
// 
//-----------------------------------------------------------------------------
