{
}
void	C_VS_UI_PARTY_MANAGER::Show()
{
	CT_Done("WnSh: C_VS_UI_PARTY_MANAGER::Show ENTER");
	if (g_pParty == NULL || m_p_image_spk == NULL)
		return;

	Rect window_rect;
	
	SetRect((RECT *)&window_rect, 0, 0, m_p_image_spk->GetWidth(PARTY_WINDOW), m_p_image_spk->GetHeight(PARTY_WINDOW));
	
	int name_x = 75, name_y = 18;
	
	COLORREF name_color;

	name_color = RGB(255, 255, 255);
	bool bl_female = g_char_slot_ingame.bl_female;

	int h =		 m_p_image_spk->GetHeight(PARTY_WINDOW);
	
	if(gpC_base->m_p_DDSurface_back->Lock())
	{
		m_p_image_spk->BltLocked(x, y, PARTY_WINDOW);
		m_p_image_spk->BltLocked(x+24, y+53, PARTY_XuanXiang);


		switch(g_eRaceInterface)
		{
		case RACE_VAMPIRE:
			if( bl_female)
				m_p_image_spk->BltLocked(x,y,PARTY_GUI_NV);
			else
				m_p_image_spk->BltLocked(x,y,PARTY_GUI_NAN);

				m_p_image_spk->BltLocked(x,y,PARTY_TouXiang_kuang);
		  break;
		case RACE_SLAYER:
			if( bl_female)
				m_p_image_spk->BltLocked(x,y,PARTY_REN_NV);
			else
				m_p_image_spk->BltLocked(x,y,PARTY_REN_NAN);

			m_p_image_spk->BltLocked(x,y,PARTY_TouXiang_kuang);
			break;
		case RACE_OUSTERS:
			m_p_image_spk->BltLocked(x,y,PARTY_MO);
			m_p_image_spk->BltLocked(x,y,PARTY_TouXiang_kuang);
			break;
		}

		POINT point;
		std::string name;
		bool bl_female;
		int spriteID = 0;
		
		
		for(int i = 0; i < 1+g_pParty->GetSize(); i++)
		{
			point.x = x;
			point.y = y;
			if(i == 0)
			{

				Rect rect;
				const int hpBarWidth = m_p_image_spk->GetWidth(PARTY_HP);
				const int hpWidth = (g_char_slot_ingame.HP_MAX <= 0) ? 0 : hpBarWidth * g_char_slot_ingame.HP / g_char_slot_ingame.HP_MAX;
				rect.Set(0, 0, hpWidth, m_p_image_spk->GetHeight(PARTY_HP));
				m_p_image_spk->BltLockedClip(point.x+52, y+33, rect, PARTY_HP);
			}
			else
			{
				PARTY_INFO *info = g_pParty->GetMemberInfo(i-1);
				if(info)
				{
					m_p_image_spk->BltLocked(point.x, point.y+h*i+17, PARTY_WINDOW);
					Rect rect;
					const int hpBarWidth = m_p_image_spk->GetWidth(PARTY_HP);
					const int hpWidth = (info->MaxHP <= 0) ? 0 : hpBarWidth * info->HP / info->MaxHP;
					rect.Set(0, 0, hpWidth, m_p_image_spk->GetHeight(PARTY_HP));
					m_p_image_spk->BltLockedClip(point.x+52, point.y+h*i+17+33, rect, PARTY_HP);
					bool is_female = info->bMale;
					switch(g_eRaceInterface)
					{
					case RACE_VAMPIRE:
						if( is_female)
							m_p_image_spk->BltLocked(point.x,point.y+h*i+17,PARTY_GUI_NAN);
						else
							m_p_image_spk->BltLocked(point.x,point.y+h*i+17,PARTY_GUI_NV);

						m_p_image_spk->BltLocked(point.x,point.y+h*i+17,PARTY_TouXiang_kuang);
						break;
					case RACE_SLAYER:
						if( is_female)
							m_p_image_spk->BltLocked(point.x,point.y+h*i+17,PARTY_REN_NAN);
						else
							m_p_image_spk->BltLocked(point.x,point.y+h*i+17,PARTY_REN_NV);

						m_p_image_spk->BltLocked(point.x,point.y+h*i+17,PARTY_TouXiang_kuang);
						break;
					case RACE_OUSTERS:
						m_p_image_spk->BltLocked(point.x,point.y+h*i+17,PARTY_MO);
						m_p_image_spk->BltLocked(point.x,point.y+h*i+17,PARTY_TouXiang_kuang);
						break;
					}
				}
			}
			
		}

		m_pC_bottom_button_group->Show();
		
		gpC_base->m_p_DDSurface_back->Unlock();
	}
	
	g_FL2_GetDC();
	g_PrintColorStr(x+name_x-g_GetStringWidth(g_char_slot_ingame.sz_name.c_str(), gpC_base->m_party_name_pi.hfont)/2, y+name_y, g_char_slot_ingame.sz_name.c_str(), gpC_base->m_party_name_pi, name_color);
	
	for(int i = 0; i < g_pParty->GetSize(); i++)
	{
		PARTY_INFO* info = g_pParty->GetMemberInfo(i);
		const char* partyName = (info != NULL) ? info->Name.GetString() : NULL;
		if(partyName != NULL && partyName[0] != '\0')
			g_PrintColorStr(x+name_x-g_GetStringWidth(partyName, gpC_base->m_party_name_pi.hfont)/2, y+name_y+window_gap*(i+1)+17, partyName, gpC_base->m_party_name_pi, name_color);
	}
	g_PrintColorStr(x+34+m_p_image_spk->GetWidth(PARTY_BUTTON_1)+2,y+56,"Exit",gpC_base->m_party_name_pi,name_color);
	if(g_pParty->IsAcceptInvite()==true)
	{
		 g_PrintColorStr(x+34,y+56,"Decline From Party",gpC_base->m_party_name_pi,name_color);
	}
	else
	{
		  g_PrintColorStr(x+34,y+56,"Allows teaming up",gpC_base->m_party_name_pi,name_color);
	}
	m_pC_bottom_button_group->ShowDescription();
	g_FL2_ReleaseDC();
}
bool	C_VS_UI_PARTY_MANAGER::IsPixel(int _x, int _y)
{
	if(m_p_image_spk == NULL)return false;
	int size;
	if(g_pParty == NULL)
		size = m_p_image_spk->GetHeight(PARTY_WINDOW)+m_p_image_spk->GetHeight(PARTY_XuanXiang);
	else
		size = (g_pParty->GetSize() +1)*(m_p_image_spk->GetHeight(PARTY_WINDOW))+m_p_image_spk->GetHeight(PARTY_XuanXiang);
	
	bool re = (_x >= x && _x < x +m_p_image_spk->GetWidth(PARTY_WINDOW) && _y >= y && _y < y + size);
	if(re == false)
		m_away_focused = -1;

	//if(Moving()) return true;
	//return IsInRect(_x, _y);
	
	return re;
}
void	C_VS_UI_PARTY_MANAGER::Start()
{
	Rect &rect = gpC_vs_ui_window_manager->GetRect(C_VS_UI_WINDOW_MANAGER::PARTY);
	if(rect.w != -1)
	{
		x = rect.x;
		y = rect.y;
	}
	
	PI_Processor::Start();
	
	gpC_window_manager->AppearWindow(this);
	
	DeleteNew(m_p_image_spk);
	m_p_image_spk = new C_SPRITE_PACK;
	m_p_image_spk->Open(SPK_VAMPIRE_PARTY);
	
	EMPTY_MOVE;
}

void C_VS_UI_PARTY_MANAGER::Finish()
{
	gpC_vs_ui_window_manager->SetAutoHide(C_VS_UI_WINDOW_MANAGER::PARTY, GetAttributes()->autohide);
	gpC_vs_ui_window_manager->SetRect(C_VS_UI_WINDOW_MANAGER::PARTY, Rect(x, y, w, h));
	
	DeleteNew(m_p_image_spk);	
	PI_Processor::Finish();
	
	gpC_window_manager->DisappearWindow(this);
}
bool	C_VS_UI_PARTY_MANAGER::MouseControl(UINT message, int _x, int _y)
{
	if (g_pParty == NULL)
		return false;
	
	Window::MouseControl(message, _x, _y);
	
	_x-=x;_y-=y;
	
	bool re = true ;
	
	re = m_pC_bottom_button_group->MouseControl(message, _x, _y-53-17);
	
		switch (message)
	{
		case M_MOVING:
			m_away_focused = (_y-17)/window_gap;
			if(m_away_focused > g_pParty->GetSize() || m_away_focused < 0)
				m_away_focused = -1;
			if(m_away_focused > 0 && m_away_focused < g_pParty->GetSize()+1)
			{
				PARTY_INFO *info = g_pParty->GetMemberInfo(m_away_focused-1);
				if(info != NULL)
				{
					static char zonename[64];
					static char zonexy[32];
					static S_DEFAULT_HELP_STRING party_string;
					ZONETABLE_INFO* pZoneInfo = (g_pZoneTable != NULL) ? g_pZoneTable->Get(info->zoneID) : NULL;
					const char* pZoneName = (pZoneInfo != NULL && pZoneInfo->Name.GetString() != NULL) ? pZoneInfo->Name.GetString() : "Unknown";
					wsprintf(zonename, "%s", pZoneName);
					wsprintf(zonexy, (*g_pGameStringTable)[UI_STRING_MESSAGE_ZONEINFO_XY].GetString(), info->zoneX, info->zoneY);
					party_string.sz_main_str = zonename;
					party_string.sz_sub_str = zonexy;
					g_descriptor_manager.Set(DID_HELP, x+9, y+1+window_gap*m_away_focused+17, (void *)&party_string,0,0);
				}
			}
			break;
			
		case M_LEFTBUTTON_DOWN:
		case M_LB_DOUBLECLICK:
			if (gpC_mouse_pointer->GetPickUpItem() == false && re)
			{
				MoveReady();
				SetOrigin(_x, _y);
				break;
			}
			break;
	}
	
	if(message == M_RIGHTBUTTON_DOWN || message == M_RIGHTBUTTON_UP)
		return false;
	
	return true;
}
void	C_VS_UI_PARTY_MANAGER::ShowButtonDescription(C_VS_UI_EVENT_BUTTON * p_button)
{
	const static char*	m_buttoninfo_string[8] = {
		(*g_pGameStringTable)[UI_STRING_MESSAGE_SET_INVITE_DENY_MODE].GetString(),
		(*g_pGameStringTable)[UI_STRING_MESSAGE_CANCEL_INVITE_DENY_MODE].GetString(),
		(*g_pGameStringTable)[UI_STRING_MESSAGE_SET_JOIN_DENY_MODE].GetString(),
		(*g_pGameStringTable)[UI_STRING_MESSAGE_CANCEL_JOIN_DENY_MODE].GetString(),
		(*g_pGameStringTable)[UI_STRING_MESSAGE_SHOW_HELP_PARTY_MANAGER].GetString(),
		(*g_pGameStringTable)[UI_STRING_MESSAGE_CLOSE_PARTY_MANAGER].GetString(),
		(*g_pGameStringTable)[UI_STRING_MESSAGE_SHOW_NO_ALPHA_WINDOW].GetString(),
		(*g_pGameStringTable)[UI_STRING_MESSAGE_EXPEL].GetString(),
	};
	
	int desc_select = 0;
	if (m_p_image_spk->IsPixel(gpC_mouse_pointer->GetX()-x-p_button->x, gpC_mouse_pointer->GetY()-y-p_button->y-window_gap-17, p_button->m_image_index))
	{
		if(p_button->GetID() == DENY_ID)
		{
			if(g_pParty->GetSize() > 0)
				desc_select += 2;
			if(g_pParty->IsAcceptInvite() == false)
				desc_select++;
		}
		else if(p_button->GetID() == AWAY_I)
		{
			   desc_select = 7;
		}
		else
			desc_select = 4+p_button->GetID()-HELP_ID;
		
		g_descriptor_manager.Set(DID_INFO, p_button->x+x, p_button->y+y+(window_default_height + window_gap*(g_pParty->GetSize()+1)), (void *)m_buttoninfo_string[desc_select],0,0);
	}	
}
void	C_VS_UI_PARTY_MANAGER::ShowButtonWidget(C_VS_UI_EVENT_BUTTON * p_button)
{
	if(m_p_image_spk == NULL)return;	
	
	if(p_button->GetFocusState())
	{
		if(p_button->GetID() == DENY_ID && g_pParty->IsAcceptInvite() == false)
			m_p_image_spk->BltLocked(p_button->x+x, p_button->y+y+53+18, PARTY_BUTTON_2_1);
		else
			m_p_image_spk->BltLocked(p_button->x+x, p_button->y+y+53+18, p_button->m_image_index+1);
	}
	else
	{
		if(p_button->GetID() == DENY_ID && g_pParty->IsAcceptInvite() == false)
			m_p_image_spk->BltLocked(p_button->x+x, p_button->y+y+53+18, PARTY_BUTTON_2_2);
		else
			m_p_image_spk->BltLocked(p_button->x+x, p_button->y+y+53+18, p_button->m_image_index);
	}
}
void C_VS_UI_PARTY_MANAGER::WindowEventReceiver(id_t event)
{
}
void C_VS_UI_PARTY_MANAGER::Run(id_t id)
{
	switch (id)
	{
	case DENY_ID:
		if(g_pParty->IsAcceptInvite())
			g_pParty->RefuseInvite();
		else
			g_pParty->AcceptInvite();
		EMPTY_MOVE;
		break;
	case CLOSE_ID:
		gpC_base->SendMessage(UI_CLOSE_PARTY_MANAGER);
		break;
		
	case AWAY_I:
		gpC_base->SendMessage(UI_AWAY_PARTY, -1);
		break;
		
	}
}

