//-----------------------------------------------------------------------------
// Show
//
// 
//-----------------------------------------------------------------------------
void C_VS_UI_HPBAR::Show()
{
	CT_Done("WnSh: C_VS_UI_HPBAR::Show ENTER pthis=%p", (void*)this);
	int hp = min(max(0, g_char_slot_ingame.HP), g_char_slot_ingame.HP_MAX);

	switch(g_eRaceInterface)
	{
	case RACE_SLAYER:
		{		
			int mp = min(max(0, g_char_slot_ingame.MP), g_char_slot_ingame.MP_MAX);

			if(gpC_base->m_p_DDSurface_back->Lock())
			{

				m_pC_hpbar_spk->BltLocked(x,y,LEFT_WIDTH_KUANGJIA);
				m_pC_hpbar_spk->BltLocked(x+m_pC_hpbar_spk->GetWidth(LEFT_WIDTH_KUANGJIA)+1,y-67+80,New_One);	
				m_pC_hpbar_spk->BltLocked(x+m_pC_hpbar_spk->GetWidth(LEFT_WIDTH_KUANGJIA)+m_pC_hpbar_spk->GetWidth(New_One)+1,y,RIGHT_WIDTH_KUANGJIA);

				//m_pC_width_button_group->Show();

				int hpbar_x = 28, hpbar_y = 4;

				Rect rect;
				//hpbar
				rect.Set(0, 0, m_pC_hpbar_spk->GetWidth(WIDTH_HPBAR_RED)*hp/max(1, g_char_slot_ingame.HP_MAX), m_pC_hpbar_spk->GetHeight(WIDTH_HPBAR_RED));
				if(g_char_slot_ingame.bl_drained)
				{
					m_pC_hpbar_spk->BltLockedClip(x+hpbar_x, y+hpbar_y, rect, BLOOD_WIDTH);
				}
				else
				{
					m_pC_hpbar_spk->BltLockedClip(x+hpbar_x-2, y+hpbar_y+15, rect, WIDTH_HPBAR_RED);
				}


				//mpbar
				rect.Set(0, 0, m_pC_hpbar_spk->GetWidth(WIDTH_MPBAR)*mp/g_char_slot_ingame.MP_MAX, m_pC_hpbar_spk->GetHeight(WIDTH_MPBAR));
				m_pC_hpbar_spk->BltLockedClip(x+hpbar_x+290+2, y+hpbar_y+15, rect, WIDTH_MPBAR);
			
				
				gpC_base->m_p_DDSurface_back->Unlock();
			}
				g_FL2_GetDC();
				char sz_tempHP[512];
				char sz_tempMP[512];
				char sz_tempLEVEL[512];

				wsprintf(sz_tempHP,"%d / %d",g_char_slot_ingame.HP,g_char_slot_ingame.HP_MAX);
				wsprintf(sz_tempMP,"%d / %d",g_char_slot_ingame.MP,g_char_slot_ingame.MP_MAX);

				if(g_char_slot_ingame.m_AdvancementLevel>0)
				wsprintf(sz_tempLEVEL,"Adv. Level: %d",g_char_slot_ingame.m_AdvancementLevel);
				else
				wsprintf(sz_tempLEVEL,"Domain Level: %d",g_char_slot_ingame.level);

				int nFontWidth = g_GetStringWidth(sz_tempHP,gpC_base->m_chatting_pi.hfont);
				int Fwidth = (190-nFontWidth)/2;

				int nFontWidthMP = g_GetStringWidth(sz_tempMP,gpC_base->m_chatting_pi.hfont);
				int FwidthMP = (190-nFontWidthMP)/2;

				int nFontWidthLEVEL = g_GetStringWidth(sz_tempLEVEL,gpC_base->m_chatting_pi.hfont);
				int FwidthLEVEL = (66-nFontWidthLEVEL)/2;

				g_PrintColorStr(x+26+Fwidth, y+4+15, sz_tempHP, gpC_base->m_chatting_pi, RGB_WHITE);
				g_PrintColorStr(x+28+290+FwidthMP, y+4+15, sz_tempMP, gpC_base->m_chatting_pi, RGB_WHITE);
				g_PrintColorStr(x+26+190+20+FwidthLEVEL, y+4+15, sz_tempLEVEL, gpC_base->m_chatting_pi, RGB_WHITE);
				g_FL2_ReleaseDC();

			//	m_pC_width_button_group->ShowDescription();

		}
		break;

	case RACE_VAMPIRE:
		{		
			if(gpC_base->m_p_DDSurface_back->Lock())
			{

					m_pC_hpbar_spk->BltLocked(x,y,LEFT_WIDTH_KUANGJIA);
					m_pC_hpbar_spk->BltLocked(x+m_pC_hpbar_spk->GetWidth(LEFT_WIDTH_KUANGJIA)+1,y-67+80,New_One);	
					m_pC_hpbar_spk->BltLocked(x+m_pC_hpbar_spk->GetWidth(LEFT_WIDTH_KUANGJIA)+m_pC_hpbar_spk->GetWidth(New_One)+1,y,RIGHT_WIDTH_KUANGJIA);

				//	m_pC_width_button_group->Show();

					int hpbar_x = 28, hpbar_y = 6;

					Rect rect;

					// hpbar
					rect.Set(0, 0, m_pC_hpbar_spk->GetWidth(WIDTH_HPBAR_RED)*hp/g_char_slot_ingame.HP_MAX, m_pC_hpbar_spk->GetHeight(WIDTH_HPBAR_RED));
					m_pC_hpbar_spk->BltLockedClip(x+hpbar_x-2, y+hpbar_y+13, rect, WIDTH_HPBAR_RED);

					// slivered hpbar
					rect.Set(m_pC_hpbar_spk->GetWidth(BLOOD_WIDTH)-m_pC_hpbar_spk->GetWidth(BLOOD_WIDTH)*g_char_slot_ingame.SILVER_HP/g_char_slot_ingame.HP_MAX, 0, m_pC_hpbar_spk->GetWidth(BLOOD_WIDTH)*g_char_slot_ingame.SILVER_HP/g_char_slot_ingame.HP_MAX, m_pC_hpbar_spk->GetHeight(BLOOD_WIDTH));
					m_pC_hpbar_spk->BltLockedClip(x+hpbar_x, y+hpbar_y+13, rect, BLOOD_WIDTH);

					rect.Set(0, m_pC_hpbar_spk->GetHeight(WIDTH_HPBAR_BAN)-m_pC_hpbar_spk->GetHeight(WIDTH_HPBAR_BAN), m_pC_hpbar_spk->GetWidth(WIDTH_HPBAR_BAN), m_pC_hpbar_spk->GetHeight(WIDTH_HPBAR_BAN));
					m_pC_hpbar_spk->BltLockedClip(x+hpbar_x+290+2, y+hpbar_y+13, rect, WIDTH_HPBAR_BAN);

					
			
				
				gpC_base->m_p_DDSurface_back->Unlock();	 
			}

				g_FL2_GetDC();
				char sz_tempHP[512];
				char sz_tempLEVEL[512];

				wsprintf(sz_tempHP,"%d / %d",g_char_slot_ingame.HP,g_char_slot_ingame.HP_MAX);
				if(g_char_slot_ingame.m_AdvancementLevel>0)
					wsprintf(sz_tempLEVEL,"Adv Level: %d",g_char_slot_ingame.m_AdvancementLevel);
				else
					wsprintf(sz_tempLEVEL,"Domain Level: %d",g_char_slot_ingame.level);

				int nFontWidth = g_GetStringWidth(sz_tempHP,gpC_base->m_chatting_pi.hfont);
				int Fwidth = (190-nFontWidth)/2;


				int nFontWidthLEVEL = g_GetStringWidth(sz_tempLEVEL,gpC_base->m_chatting_pi.hfont);
				int FwidthLEVEL = (70-nFontWidthLEVEL)/2;

				g_PrintColorStr(x+26+Fwidth, y+4+15, sz_tempHP, gpC_base->m_chatting_pi, RGB_WHITE);
				g_PrintColorStr(x+26+190+14+FwidthLEVEL, y+4+15, sz_tempLEVEL, gpC_base->m_chatting_pi, RGB_WHITE);
				g_FL2_ReleaseDC();
			
			//	m_pC_width_button_group->ShowDescription();

		}
		break;

	case RACE_OUSTERS:
		{
			if(gpC_base->m_p_DDSurface_back->Lock())
			{
				m_pC_hpbar_spk->BltLocked(x,y,LEFT_WIDTH_KUANGJIA);
				m_pC_hpbar_spk->BltLocked(x+m_pC_hpbar_spk->GetWidth(LEFT_WIDTH_KUANGJIA)+1,y-67+80,New_One);	
				m_pC_hpbar_spk->BltLocked(x+m_pC_hpbar_spk->GetWidth(LEFT_WIDTH_KUANGJIA)+m_pC_hpbar_spk->GetWidth(New_One)+1,y,RIGHT_WIDTH_KUANGJIA);

				int MaxMP = max(g_char_slot_ingame.MP_MAX, 1);
				int Magnification = min(2, (g_char_slot_ingame.MP / (MaxMP+1))) ;
				int CurrentMP = g_char_slot_ingame.MP - (MaxMP*Magnification);
				int mp = min(max(0, g_char_slot_ingame.MP), MaxMP);

				//m_pC_width_button_group->Show();

				int hpbar_x = 28, hpbar_y = 6;

					Rect rect;

					// hpbar
					rect.Set(0, 0, m_pC_hpbar_spk->GetWidth(WIDTH_HPBAR_RED)*hp/g_char_slot_ingame.HP_MAX, m_pC_hpbar_spk->GetHeight(WIDTH_HPBAR_RED));
					m_pC_hpbar_spk->BltLockedClip(x+hpbar_x-2, y+hpbar_y+13, rect, WIDTH_HPBAR_RED);
	
					rect.Set(m_pC_hpbar_spk->GetWidth(BLOOD_WIDTH)-m_pC_hpbar_spk->GetWidth(BLOOD_WIDTH)*g_char_slot_ingame.SILVER_HP/g_char_slot_ingame.HP_MAX, 0, m_pC_hpbar_spk->GetWidth(BLOOD_WIDTH)*g_char_slot_ingame.SILVER_HP/g_char_slot_ingame.HP_MAX, m_pC_hpbar_spk->GetHeight(BLOOD_WIDTH));
					m_pC_hpbar_spk->BltLockedClip(x+hpbar_x, y+hpbar_y+13, rect, BLOOD_WIDTH);

					rect.Set(0, m_pC_hpbar_spk->GetHeight(WIDTH_HPBAR_BAN)-m_pC_hpbar_spk->GetHeight(WIDTH_HPBAR_BAN), m_pC_hpbar_spk->GetWidth(WIDTH_HPBAR_BAN), m_pC_hpbar_spk->GetHeight(WIDTH_HPBAR_BAN));
					m_pC_hpbar_spk->BltLockedClip(x+hpbar_x+290+2, y+hpbar_y+13, rect, WIDTH_HPBAR_BAN);

					//mpbar
					if(Magnification == 0)
					{
						rect.Set(0, 0, m_pC_hpbar_spk->GetWidth(WIDTH_HPBAR_YELLOW)*mp/MaxMP, m_pC_hpbar_spk->GetHeight(WIDTH_HPBAR_YELLOW));
						m_pC_hpbar_spk->BltLockedClip(x+hpbar_x+290+2, y+hpbar_y+13, rect, WIDTH_HPBAR_YELLOW);
					}
					else if( Magnification == 1)
					{
						int sprIndex1 = WIDTH_HPBAR_GREEN +((BYTE)m_small_mode*4);

						rect.Set(0, 0, m_pC_hpbar_spk->GetWidth(WIDTH_HPBAR_YELLOW), m_pC_hpbar_spk->GetHeight(WIDTH_HPBAR_YELLOW));
						m_pC_hpbar_spk->BltLockedClip(x+hpbar_x+290+2, y+hpbar_y+13, rect, WIDTH_HPBAR_YELLOW);
						rect.Set(0, 0, m_pC_hpbar_spk->GetWidth(sprIndex1)*CurrentMP/MaxMP, m_pC_hpbar_spk->GetHeight(sprIndex1));
						m_pC_hpbar_spk->BltLockedClip(x+hpbar_x+290+2, y+hpbar_y+13, rect, sprIndex1);
					}
					else if( Magnification == 2)
					{
						int sprIndex1 = WIDTH_HPBAR_GREEN;
						int sprIndex2 = WIDTH_HPBAR_GREEN;

						rect.Set(0, 0, m_pC_hpbar_spk->GetWidth(sprIndex1), m_pC_hpbar_spk->GetHeight(sprIndex1));
						m_pC_hpbar_spk->BltLockedClip(x+hpbar_x+290+2, y+hpbar_y+13, rect, sprIndex1);
						rect.Set(0, 0, m_pC_hpbar_spk->GetWidth(sprIndex2)*CurrentMP/MaxMP, m_pC_hpbar_spk->GetHeight(sprIndex2));
						m_pC_hpbar_spk->BltLockedClip(x+hpbar_x+290+2, y+hpbar_y+13, rect, sprIndex2);
					}

				
				gpC_base->m_p_DDSurface_back->Unlock();		 
			}

				g_FL2_GetDC();
				char sz_tempHP[512];
				char sz_tempLEVEL[512];

				wsprintf(sz_tempHP,"%d / %d",g_char_slot_ingame.HP,g_char_slot_ingame.HP_MAX);
				if(g_char_slot_ingame.m_AdvancementLevel>0)
					wsprintf(sz_tempLEVEL,"Adv Level: %d",g_char_slot_ingame.m_AdvancementLevel);
				else
					wsprintf(sz_tempLEVEL,"Domain Level: %d",g_char_slot_ingame.level);


				char sz_tempMP[512];

				wsprintf(sz_tempMP,"%d / %d",g_char_slot_ingame.MP,g_char_slot_ingame.MP_MAX);

				int nFontWidth = g_GetStringWidth(sz_tempHP,gpC_base->m_chatting_pi.hfont);
				int Fwidth = (190-nFontWidth)/2;

				int nFontWidthLEVEL = g_GetStringWidth(sz_tempLEVEL,gpC_base->m_chatting_pi.hfont);
				int FwidthLEVEL = (70-nFontWidthLEVEL)/2;


				int nFontWidthMP = g_GetStringWidth(sz_tempMP,gpC_base->m_chatting_pi.hfont);
				int FwidthMP = (190-nFontWidthMP)/2;

				g_PrintColorStr(x+26+Fwidth, y+4+15, sz_tempHP, gpC_base->m_chatting_pi, RGB_WHITE);
				g_PrintColorStr(x+28+290+FwidthMP, y+4+15, sz_tempMP, gpC_base->m_chatting_pi, RGB_WHITE);
				g_PrintColorStr(x+26+190+14+FwidthLEVEL, y+4+15, sz_tempLEVEL, gpC_base->m_chatting_pi, RGB_WHITE);
				g_FL2_ReleaseDC();

			//	m_pC_width_button_group->ShowDescription();

		}
		break;
	}	
}

//-----------------------------------------------------------------------------
// Start
//
// 
//-----------------------------------------------------------------------------
void C_VS_UI_HPBAR::Start()
{
	PI_Processor::Start();

	//m_pC_small_width_button_group->Init();
	//m_pC_small_height_button_group->Init();
	//m_pC_width_button_group->Init();
	//m_pC_height_button_group->Init();

	gpC_window_manager->AppearWindow(this);

	AttrAutoHide(gpC_vs_ui_window_manager->GetAutoHide(C_VS_UI_WINDOW_MANAGER::HPBAR));
	//if(m_width_mode == gpC_vs_ui_window_manager->IsHPBarHeight())Run(CHANGE_ID);
	//if(gpC_vs_ui_window_manager->IsHPBarSmall() != m_small_mode)Run(RESIZE_ID);

	Rect &rect = gpC_vs_ui_window_manager->GetRect(C_VS_UI_WINDOW_MANAGER::HPBAR);
	if(rect.w != -1)
	{
		x = rect.x;
		y = rect.y;
	}

	// 2026-09-03 R5 — per-resolution defter oncelikli
	{
		int px = 0, py = 0;
		if (Phoenix_HudLayout_Get(g_pUserInformation->iResolution_x,
			g_pUserInformation->iResolution_y,
			(int)C_VS_UI_WINDOW_MANAGER::HPBAR, &px, &py))
		{
			x = px;
			y = py;
		}
	}
}

void C_VS_UI_HPBAR::Finish()
{
	gpC_vs_ui_window_manager->SetAutoHide(C_VS_UI_WINDOW_MANAGER::HPBAR, GetAttributes()->autohide);
	gpC_vs_ui_window_manager->SetRect(C_VS_UI_WINDOW_MANAGER::HPBAR, Rect(x, y, w, h));
	// 2026-09-03 R5 — mevcut cozunurlugun defter kaydi da guncellenir
	Phoenix_HudLayout_Set(g_pUserInformation->iResolution_x, g_pUserInformation->iResolution_y,
		(int)C_VS_UI_WINDOW_MANAGER::HPBAR, x, y);
	gpC_vs_ui_window_manager->SetHPBarHeight(!m_width_mode);
	gpC_vs_ui_window_manager->SetHPBarSmall(m_small_mode);

	PI_Processor::Finish();

	gpC_window_manager->DisappearWindow(this);

}

