C_VS_UI_BLOOD_BURST::C_VS_UI_BLOOD_BURST()
{
	m_pC_BloodBurst_spk = NULL;
	
	AttrTopmost(false);
	AttrPin(true);

	g_RegisterWindow(this);
	
	m_bGageAttackFull = false;
	m_bGageDefenseFull = false;
	m_bGagePartyFull = false;

	
	m_iAttackGage	=	0	;
	m_iDefenseGage	=	0	;
	m_iPartyGage	=	0	;


	m_dw_prev_Attacktickcount	=	0	;
	m_dw_prev_Defensetickcount	=	0	;
	m_dw_prev_Partyickcount		=	0	;

	m_bAttackTimerCheck		=	false;
	m_bDefenseTimerCheck	=	false;
	m_bPartyTimerCheck		=	false;
	
	m_fAttackGageStartPosition = 0.0f ; 
	m_fDefenseGageStartPosition = 0.0f ; 
	m_fPartyGageStartPosition = 0.0f ; 


	switch(g_eRaceInterface)
	{
	case RACE_SLAYER:
		m_pC_BloodBurst_spk = new C_SPRITE_PACK(SPK_BLOOD_BRUST_VAMPIRE);
		break;

	case RACE_VAMPIRE:
		m_pC_BloodBurst_spk = new C_SPRITE_PACK(SPK_BLOOD_BRUST_VAMPIRE);
		break;

	case RACE_OUSTERS:
		m_pC_BloodBurst_spk = new C_SPRITE_PACK(SPK_BLOOD_BRUST_VAMPIRE);
		break;	
	}
	
	// FAZ 4 (2026-05-03): hardcoded x=255 (800x600 odaklı) → res-aware center.
	Set(255 + (g_pUserInformation->iResolution_x - 800)/2, g_pUserInformation->iResolution_y-125, m_pC_BloodBurst_spk->GetWidth(PARTY_MAIN)*3, m_pC_BloodBurst_spk->GetHeight(PARTY_MAIN));

	m_pC_width_button_group  = new ButtonGroup(this);

	m_pC_width_button_group->Add(new C_VS_UI_EVENT_BUTTON(x+33+33+33, 33, m_pC_BloodBurst_spk->GetWidth(ATTACK_BUTTON), m_pC_BloodBurst_spk->GetHeight(ATTACK_BUTTON), ATTACK_ID, this, ATTACK_BUTTON));
	m_pC_width_button_group->Add(new C_VS_UI_EVENT_BUTTON(x+33+33+33,33, m_pC_BloodBurst_spk->GetWidth(DEFENSE_BUTTON), m_pC_BloodBurst_spk->GetHeight(DEFENSE_BUTTON), DEFENSE_ID, this, DEFENSE_BUTTON));
	m_pC_width_button_group->Add(new C_VS_UI_EVENT_BUTTON(x+33+33+33, 33,m_pC_BloodBurst_spk->GetWidth(PARTY_BUTTON), m_pC_BloodBurst_spk->GetHeight(PARTY_BUTTON), PARTY_ID, this, PARTY_BUTTON));

}

C_VS_UI_BLOOD_BURST::~C_VS_UI_BLOOD_BURST()
{
	gpC_vs_ui_window_manager->SetRect(C_VS_UI_WINDOW_MANAGER::BLOOD_BURST_WINDOW, Rect(x, y, w, h));
	g_UnregisterWindow(this);
	DeleteNew(m_pC_width_button_group);
	if(m_pC_BloodBurst_spk)
	{
		DeleteNew(m_pC_BloodBurst_spk);
		m_pC_BloodBurst_spk = NULL;
	}
}

void	C_VS_UI_BLOOD_BURST::ShowButtonWidget(C_VS_UI_EVENT_BUTTON * p_button)
{
	

	if((p_button->m_image_index == ATTACK_BUTTON   && m_bGageAttackFull)  ||
			 (p_button->m_image_index == DEFENSE_BUTTON && m_bGageDefenseFull) ||
			 ((p_button->m_image_index == PARTY_BUTTON && m_bGagePartyFull) && (g_pParty->GetSize() > 0))) 	
	{
		if(p_button->GetFocusState())
		{
			if(p_button->GetPressState())
				m_pC_BloodBurst_spk->BltLocked(x + p_button->x, y + p_button->y, p_button->m_image_index);
			else
				m_pC_BloodBurst_spk->BltLocked(x + p_button->x, y + p_button->y, p_button->m_image_index);
		}
		else
		{
			if(p_button->GetPressState())
				m_pC_BloodBurst_spk->BltLocked(x + p_button->x, y + p_button->y, p_button->m_image_index);
			else
				m_pC_BloodBurst_spk->BltLocked(x + p_button->x, y + p_button->y, p_button->m_image_index);
		}
	}


}

