void	C_VS_UI_BLOOD_BURST::Show()
{
	CT_Done("WnSh: C_VS_UI_BLOOD_BURST::Show ENTER");
	Rect RectAttack ;
	Rect RectDefense ;
	Rect RectParty ;

	bool showbuttonnow = false;
	if(gpC_base->m_p_DDSurface_back->Lock())
	{

		int reX = m_pC_BloodBurst_spk->GetWidth(PARTY_MAIN);


		C_VS_UI_EVENT_BUTTON  *pMoveButton = m_pC_width_button_group->GetButton(ATTACK_ID) ;
		C_VS_UI_EVENT_BUTTON  *pMoveButton2 = m_pC_width_button_group->GetButton(DEFENSE_ID) ;
		C_VS_UI_EVENT_BUTTON  *pMoveButton3 = m_pC_width_button_group->GetButton(PARTY_ID) ;

		int currentAttackGage = g_char_slot_ingame.AttackBloodBurstPoint;
		int RectAttackHight = m_pC_BloodBurst_spk->GetHeight(PARTY_RED)*(ATTACK_MAX_POINT-currentAttackGage)/ATTACK_MAX_POINT;
		Rect rect(0,RectAttackHight, m_pC_BloodBurst_spk->GetWidth(PARTY_RED),m_pC_BloodBurst_spk->GetHeight(PARTY_RED)-RectAttackHight);
		m_pC_BloodBurst_spk->BltLockedClip(x, y, rect, PARTY_RED);

		int currentDefenseGage = g_char_slot_ingame.DefenseBloodBurstPoint;
		int RectDefenseHight = m_pC_BloodBurst_spk->GetHeight(PARTY_BLUE)*(DEFENSE_MAX_POINT-currentDefenseGage)/DEFENSE_MAX_POINT;
		Rect rect2(0,RectDefenseHight, m_pC_BloodBurst_spk->GetWidth(PARTY_BLUE),m_pC_BloodBurst_spk->GetHeight(PARTY_BLUE)-RectDefenseHight);
		m_pC_BloodBurst_spk->BltLockedClip(x+reX, y, rect2, PARTY_BLUE);


		m_pC_BloodBurst_spk->BltLocked(x, y, PARTY_MAIN);
		m_pC_BloodBurst_spk->BltLocked(x, y, ATTACK_BUTTON);
		m_pC_BloodBurst_spk->BltLocked(x+reX, y, PARTY_MAIN);
		m_pC_BloodBurst_spk->BltLocked(x+reX, y, DEFENSE_BUTTON);

		if(m_bGageAttackFull==false  && currentAttackGage == ATTACK_MAX_POINT)
		{
			m_bGageAttackFull =!m_bGageAttackFull;
		}
		if(m_bGageDefenseFull==false && currentDefenseGage == DEFENSE_MAX_POINT)
		{
			m_bGageDefenseFull = !m_bGageDefenseFull;
		}

		if(m_bGageAttackFull == true)
		{
		//	C_VS_UI_EVENT_BUTTON  *pMoveButton = m_pC_width_button_group->GetButton(ATTACK_ID) ;

			if( pMoveButton != NULL)
			{
				int rx =x;
				int ry = y+33;
				rx-=x;ry-=y;
				pMoveButton->Set(rx,h-ry,m_pC_BloodBurst_spk->GetWidth(ATTACK_BUTTON),m_pC_BloodBurst_spk->GetHeight(ATTACK_BUTTON));
			}
			showbuttonnow = true;
		}
		if(m_bGageDefenseFull == true)
		{
		//	C_VS_UI_EVENT_BUTTON  *pMoveButton2 = m_pC_width_button_group->GetButton(DEFENSE_ID) ;

			if( pMoveButton2 != NULL)
			{
				int rx =x+reX;
				int ry = y+33;
				rx-=x;ry-=y;
				pMoveButton2->Set(rx,h-ry,m_pC_BloodBurst_spk->GetWidth(DEFENSE_BUTTON),m_pC_BloodBurst_spk->GetHeight(DEFENSE_BUTTON));
			}
			showbuttonnow = true;
		}


		RectAttack.Set(x,y,m_pC_BloodBurst_spk->GetWidth(PARTY_MAIN) ,m_pC_BloodBurst_spk->GetHeight(PARTY_MAIN)) ;
		RectDefense.Set(x+reX,y,m_pC_BloodBurst_spk->GetWidth(PARTY_MAIN) ,m_pC_BloodBurst_spk->GetHeight(PARTY_MAIN)) ;
		if(g_pParty->GetSize() > 0)
		{
			int currentPartyGage = g_char_slot_ingame.PartyBloodBurstPoint;
			int RectPartyHight = m_pC_BloodBurst_spk->GetHeight(PARTY_BLUE)*(PARTY_MAX_POINT-currentPartyGage)/PARTY_MAX_POINT;
			Rect rect3(0,RectPartyHight, m_pC_BloodBurst_spk->GetWidth(PARTY_BLUE),m_pC_BloodBurst_spk->GetHeight(PARTY_BLUE)-RectPartyHight);
			m_pC_BloodBurst_spk->BltLockedClip(x+reX*2, y, rect3, PARTY_BLUE);


			m_pC_BloodBurst_spk->BltLocked(x+reX*2, y, PARTY_MAIN);
			m_pC_BloodBurst_spk->BltLocked(x+reX*2,y,PARTY_BUTTON);

			RectParty.Set(x+reX*2,y,m_pC_BloodBurst_spk->GetWidth(PARTY_MAIN) ,m_pC_BloodBurst_spk->GetHeight(PARTY_MAIN)) ;

			if(!m_bGagePartyFull && currentPartyGage == PARTY_MAX_POINT)
			{
				m_bGagePartyFull = !m_bGagePartyFull;
			}

			if(m_bGagePartyFull == true)
			{
		//		C_VS_UI_EVENT_BUTTON  *pMoveButton3 = m_pC_width_button_group->GetButton(PARTY_ID) ;

				if( pMoveButton3 != NULL)
				{
					int rx =x+reX*2;
					int ry = y+33;
					rx-=x;ry-=y;
					pMoveButton3->Set(rx,h-ry,m_pC_BloodBurst_spk->GetWidth(PARTY_BUTTON),m_pC_BloodBurst_spk->GetHeight(PARTY_BUTTON));
					showbuttonnow = true;
				}
			}
		}
		if(showbuttonnow == true)
		{
			m_pC_width_button_group->Show();
		}
		else if(pMoveButton!=NULL)
		{
			m_pC_width_button_group->Delete(pMoveButton);
		}
		else if(pMoveButton2 !=NULL)
		{
			m_pC_width_button_group->Delete(pMoveButton2);
		}
		else if(pMoveButton3 !=NULL)
		{
			m_pC_width_button_group->Delete(pMoveButton3);
		}


		gpC_base->m_p_DDSurface_back->Unlock();
	} 

	
	int print_x = gpC_mouse_pointer->GetPointerX();
	int print_y = gpC_mouse_pointer->GetPointerY();
	int color = 0;
	
	static std::string bloodburst_string[1];
	const static char *help_string[1] =  {NULL} ;

	if(RectAttack.IsInRect(gpC_mouse_pointer->GetPointerX() , gpC_mouse_pointer->GetPointerY())) // && m_iAttackGage)
	{
		char temp_string[512];
		wsprintf(temp_string, (*g_pGameStringTable)[UI_STRING_MESSAGE_BLOOD_BURST_ATTACK].GetString(), m_iAttackGage , ATTACK_MAX_POINT);
		bloodburst_string[0]=temp_string;
					
		help_string[0] = bloodburst_string[0].c_str();
		g_descriptor_manager.Set(DID_HELP, print_x+30, print_y, (void *)help_string, 0, color);

	}
	else if(RectDefense.IsInRect(gpC_mouse_pointer->GetPointerX() , gpC_mouse_pointer->GetPointerY())) //  && m_iDefenseGage)
	{
		char temp_string[512];
		wsprintf(temp_string, (*g_pGameStringTable)[UI_STRING_MESSAGE_BLOOD_BURST_DEFENSE].GetString(), m_iDefenseGage , DEFENSE_MAX_POINT);
		bloodburst_string[0]=temp_string;
					
		help_string[0] = bloodburst_string[0].c_str();
		g_descriptor_manager.Set(DID_HELP, print_x+30, print_y, (void *)help_string, 0, color);
	}
	else if(RectParty.IsInRect(gpC_mouse_pointer->GetPointerX() , gpC_mouse_pointer->GetPointerY()))// && m_iPartyGage )
	{
		char temp_string[512];
		wsprintf(temp_string, (*g_pGameStringTable)[UI_STRING_MESSAGE_BLOOD_BURST_PARTY].GetString(), m_iPartyGage , PARTY_MAX_POINT);
		bloodburst_string[0]=temp_string;
					
		help_string[0] = bloodburst_string[0].c_str();
		g_descriptor_manager.Set(DID_HELP, print_x+30, print_y, (void *)help_string, 0, color);
	}
}

void	C_VS_UI_BLOOD_BURST::Process()
{
	ProcessHide();
	
	m_pC_width_button_group->Process();


}
void	C_VS_UI_BLOOD_BURST::Start()
{
	
	Rect &rect = gpC_vs_ui_window_manager->GetRect(C_VS_UI_WINDOW_MANAGER::BLOOD_BURST_WINDOW);
	if(rect.w != -1)
	{
		x = rect.x;
		y = rect.y;
	}	

	// 2026-09-03 R5 — per-resolution defter oncelikli
	{
		int px = 0, py = 0;
		if (Phoenix_HudLayout_Get(g_pUserInformation->iResolution_x,
			g_pUserInformation->iResolution_y,
			(int)C_VS_UI_WINDOW_MANAGER::BLOOD_BURST_WINDOW, &px, &py))
		{
			x = px;
			y = py;
		}
	}

	PI_Processor::Start();
	SetGage()	;
	m_pC_width_button_group->Init();
	gpC_window_manager->AppearWindow(this);

	
}

void	C_VS_UI_BLOOD_BURST::Finish()
{
	gpC_vs_ui_window_manager->SetRect(C_VS_UI_WINDOW_MANAGER::BLOOD_BURST_WINDOW, Rect(x, y, w, h));
	// 2026-09-03 R5 — mevcut cozunurlugun defter kaydi da guncellenir
	Phoenix_HudLayout_Set(g_pUserInformation->iResolution_x, g_pUserInformation->iResolution_y,
		(int)C_VS_UI_WINDOW_MANAGER::BLOOD_BURST_WINDOW, x, y);
	PI_Processor::Finish();

	gpC_window_manager->DisappearWindow(this);
}



