namespace
{
	const int EFFECT_STATUS_CELL_SIZE = 36;
	const int EFFECT_STATUS_WIDTH_COLUMNS = 24;
	const int EFFECT_STATUS_WIDTH_ROWS = 2;
	const int EFFECT_STATUS_WIDTH_VISIBLE = EFFECT_STATUS_WIDTH_COLUMNS * EFFECT_STATUS_WIDTH_ROWS;
	const int EFFECT_STATUS_WARINFO_START_Y = EFFECT_STATUS_WIDTH_ROWS * EFFECT_STATUS_CELL_SIZE;
}

