//-----------------------------------------------------------------------------
// IsPixel
//
// 
//-----------------------------------------------------------------------------
bool C_VS_UI_EFFECT_STATUS::IsPixel(int _x, int _y)
{
	if(Moving()) return true;
	if(m_width_mode)
	{
		const int localX = _x - x;
		const int localY = _y - y;
		const int visibleStatus = min(EFFECT_STATUS_WIDTH_VISIBLE, (int)g_char_slot_ingame.STATUS.size());
		if(localX >= 0 && localX < EFFECT_STATUS_WIDTH_COLUMNS*EFFECT_STATUS_CELL_SIZE &&
			localY >= 0 && localY < EFFECT_STATUS_WARINFO_START_Y)
		{
			const int index = (localY / EFFECT_STATUS_CELL_SIZE) * EFFECT_STATUS_WIDTH_COLUMNS + (localX / EFFECT_STATUS_CELL_SIZE);
			if(index < visibleStatus)
				return true;
		}

		if(localX >= 0 && localX < EFFECT_STATUS_CELL_SIZE &&
			localY >= EFFECT_STATUS_WARINFO_START_Y &&
			localY < EFFECT_STATUS_WARINFO_START_Y + (int)g_pUserInformation->WarInfo.size()*EFFECT_STATUS_CELL_SIZE)
		{
			return true;
		}
		return false;
	}
	return IsInRect(_x, _y);
	//	if(m_width_mode)
	//		return m_pC_EFFECT_STATUS_spk->IsPixel(_x-x, _y-y, MAIN_WIDTH);
	//	else
	//		return m_pC_EFFECT_STATUS_spk->IsPixel(_x-x, _y-y, MAIN_HEIGHT);
	
	//	return false;
	//	return m_pC_charinfo->IsPixel(SCR2WIN_X(_x), SCR2WIN_Y(_y), CHARINFO_WINDOW);
}

