bool	C_VS_UI_MILITARYDLG::IsPixel(int _x, int _y)
{
	if(Moving()) return true;
	return IsInRect(_x, _y);
}

bool	C_VS_UI_MILITARYDLG::RareSkillInfoMouseControl(UINT message, int _x, int _y)
{

	SKILL_STEP nRareSkillStep;
	static SKILLDOMAIN skillDomain = m_skill_domain;

	// ������ �´� �׸� ����� �����Ѵ�.
	switch(g_eRaceInterface)
	{
	case RACE_VAMPIRE:
		nRareSkillStep						= SKILL_STEP_VAMPIRE_RARE;
		m_skill_domain = SKILLDOMAIN_VAMPIRE;
		break;
	case RACE_OUSTERS:
		nRareSkillStep						= SKILL_STEP_OUSTERS_RARE;
		m_skill_domain = SKILLDOMAIN_OUSTERS;
		break;
		//	case RACE_SLAYER:	
	default: // �⺻������ �����̾� Ȥ�� �𸣴� -��-)
		nRareSkillStep						= SKILL_STEP_SLAYER_RARE;
		skillDomain							= SKILLDOMAIN_ETC;
		break;
	}

	CPoint	mousePoint(_x, _y);
	CRect	skillDescRect(CPoint(30, 53), CSize(262, 240));

	if(skillDescRect.PtInRect(mousePoint))
	{
		if(!m_rare_skill_id_vec.empty())
		{
			int num = (_y - skillDescRect.top) / 60;
			num += max(0, m_pC_rare_skill_scroll_bar->GetScrollPos());

			if(num >= m_rare_skill_id_vec.size()) return false;

			const int id = m_rare_skill_id_vec[num];

			g_descriptor_manager.Set(DID_SKILLTREE, x + _x, y + _y, (void *)&skillDomain, id, 0);
			m_focused_skill_id = id;
		}
	}


	return true;
}
void C_VS_UI_MILITARYDLG::ShowButtonWidget(C_VS_UI_EVENT_BUTTON * p_button)
{
	if ( p_button->GetID() >= Button_Skill && p_button->GetID() < Button_Blade )
	{
		if ( p_button->GetID() == Button_Skill && m_ui_index==0)
			m_pC_Skill_spk->BltLocked(x + p_button->x, y + p_button->y, p_button->m_image_index + 2);
		else if ( p_button->GetID() == Button_RankGem && m_ui_index==1)
			m_pC_Skill_spk->BltLocked(x + p_button->x, y + p_button->y, p_button->m_image_index + 2);
		else if ( p_button->GetID() == Button_Guild && m_ui_index==2)
			m_pC_Skill_spk->BltLocked(x + p_button->x, y + p_button->y, p_button->m_image_index + 2);
		else
			m_pC_Skill_spk->BltLocked(x + p_button->x, y + p_button->y, p_button->m_image_index);
	}
	else  //close Button
	{
		m_pC_Skill_spk->BltLocked(x + p_button->x, y + p_button->y, p_button->m_image_index);
	} 
	if ( p_button->GetID() >= Button_Blade && p_button->GetID() < Button_mozhan )
	{
		if ( p_button->GetID() == Button_Blade && m_slayer_job_index==0)
			m_pC_Skill_spk->BltLocked(x + p_button->x, y + p_button->y, p_button->m_image_index + 2);
		else if ( p_button->GetID() == Button_Sword && m_slayer_job_index==1)
			m_pC_Skill_spk->BltLocked(x + p_button->x, y + p_button->y, p_button->m_image_index + 2);
		else if ( p_button->GetID() == Button_Gun && m_slayer_job_index==2)
			m_pC_Skill_spk->BltLocked(x + p_button->x, y + p_button->y, p_button->m_image_index + 2);
		else if ( p_button->GetID() == Button_Heal && m_slayer_job_index==3)
			m_pC_Skill_spk->BltLocked(x + p_button->x, y + p_button->y, p_button->m_image_index + 2);
		else if ( p_button->GetID() == Button_Enchant && m_slayer_job_index==4)
			m_pC_Skill_spk->BltLocked(x + p_button->x, y + p_button->y, p_button->m_image_index + 2);
		else
			m_pC_Skill_spk->BltLocked(x + p_button->x, y + p_button->y, p_button->m_image_index);
	}

	if ( p_button->GetID() >= Button_mozhan && p_button->GetID() <= Button_mofa )
	{
		if ( p_button->GetID() == Button_mozhan && m_ouster_job_index==0)
			m_pC_Skill_spk->BltLocked(x + p_button->x, y + p_button->y, p_button->m_image_index + 2);
		else if ( p_button->GetID() == Button_mofa && m_ouster_job_index==1)
			m_pC_Skill_spk->BltLocked(x + p_button->x, y + p_button->y, p_button->m_image_index + 2);
		else
			m_pC_Skill_spk->BltLocked(x + p_button->x, y + p_button->y, p_button->m_image_index);
	}
	if(b_showRankGem)
	{
		if ( p_button->GetID() == Button_Skill && m_ui_index==0)
			m_pC_Skill_spk->BltLocked(x + p_button->x, y + p_button->y, p_button->m_image_index + 2);
		if ( p_button->GetID() >= Button_Tab0 && p_button->GetID() < Button_Close )
		{
			if ( p_button->GetID() == m_nPageIndex )
				m_pC_Skill_spk->BltLocked(x + p_button->x, y + p_button->y, p_button->m_image_index + 2);
			else
				m_pC_Skill_spk->BltLocked(x + p_button->x, y + p_button->y, p_button->m_image_index);
		}
	}
}

