void C_VS_UI_MILITARYDLG::Run(id_t id)
{
	int m_iDomain = id + 3;
	switch (id)
	{
	case Button_Tab0:
		m_nPageIndex = id;
		break;

	case Button_Tab1:
		m_nPageIndex = id;
		break;

	case Button_Tab2:
		m_nPageIndex = id;
		break;

	case Button_Close:
		m_ui_index = 0;
		b_showRankGem = false;
		gC_vs_ui.CloseMilitary();
		break;

	case Button_Skill:
		switch (g_eRaceInterface)
		{
		case RACE_VAMPIRE:
			m_ui_index = 0;
			if (b_showRankGem)
				b_showRankGem = false;
			break;

		case RACE_SLAYER:
			m_ui_index = 0;
			m_slayer_job_index = 0;
			if (!b_showSword)
				b_showSword = true;
			if (b_showRankGem)
				b_showRankGem = false;
			if (b_showMozhan)
				b_showMozhan = false;
			break;

		case RACE_OUSTERS:
			m_ui_index = 0;
			if (!b_showMozhan)
				b_showMozhan = true;
			if (b_showRankGem)
				b_showRankGem = false;
			if (b_showSword)
				b_showSword = false;
			break;
		}
		// gC_vs_ui.RunInfo(C_VS_UI_INFO::SKILL_INFO_MODE);
		break;

	case Button_Blade:
	case Button_Sword:
	case Button_Gun:
	case Button_Heal:
	case Button_Enchant:
		m_slayer_job_index = id - Button_Blade;
		break;

	case Button_mozhan:
	case Button_mofa:
		m_ouster_job_index = id - Button_mozhan;
		m_skill_domain = SKILLDOMAIN_OUSTERS;

		if (m_iDomain >= Button_mozhan && m_iDomain <= Button_mofa && m_skill_domain == SKILLDOMAIN_OUSTERS)
		{
			int xMax = 0, yMax = 0;

			const int domain_level = (*g_pSkillManager)[SKILLDOMAIN_OUSTERS].GetDomainLevel();
			SKILL_STEP step = (SKILL_STEP)(m_iDomain - Button_mozhan + SKILL_STEP_OUSTERS_COMBAT);
			if ((*g_pSkillManager)[SKILLDOMAIN_OUSTERS].IsExistSkillStep(step))
			{
				MSkillDomain::SKILL_STEP_LIST list = *((*g_pSkillManager)[SKILLDOMAIN_OUSTERS].GetSkillStepList(step));
				MSkillDomain::SKILL_STEP_LIST::iterator ss = list.begin();
				while (ss != list.end())
				{
					const ACTIONINFO SkillID = (ACTIONINFO)*ss;
					MSkillDomain::SKILLSTATUS status = (*g_pSkillManager)[SKILLDOMAIN_OUSTERS].GetSkillStatus(SkillID);
					const int sprID = (*g_pSkillInfoTable)[SkillID].GetSpriteID();
					const int sprX = (*g_pSkillInfoTable)[SkillID].GetX();
					const int sprY = (*g_pSkillInfoTable)[SkillID].GetY();

					xMax = max(sprX + 60, xMax);
					yMax = max(sprY + 60, yMax);

					ss++;
				}
			}
		}
		break;

	case Button_RankGem:
		m_ui_index = 1;
		b_showRankGem = true;
		break;

	case Button_Guild:
		m_ui_index = 0;
		b_showRankGem = false;
		gC_vs_ui.CloseMilitary();
		break;

	case Button_Down:
		if (button_time > 0)
		{
			mozhan_gap += 50;
			button_time = button_time - 1;
		}
		break;

	case Button_Up:
		if (5 - button_time > 0)
		{
			mozhan_gap -= 50;
			button_time = button_time + 1;
		}
		break;

	case Button_Vampire_adv_skill_1:
	case Button_Vampire_adv_skill_2:
	case Button_Vampire_adv_skill_3:
	case Button_Vampire_adv_skill_4:
	case Button_Vampire_adv_skill_5:
	{
		switch (g_eRaceInterface)
		{
		case RACE_VAMPIRE:
		{
			if (!m_advance_skill_id_vec.empty() && id <= Button_Vampire_adv_skill_5 && id >= Button_Vampire_adv_skill_1)
			{
				MSkillDomain::SKILL_STEP_LIST::iterator ss = m_advance_skill_id_vec.begin() + (id - Button_Vampire_adv_skill_1);
				const ACTIONINFO SkillID = (ACTIONINFO)*ss;
				m_selected_ACSkillID = SkillID;
				const int domain_level = (*g_pSkillManager)[SKILLDOMAIN_VAMPIRE].GetDomainLevel();
				const int advance_level = g_char_slot_ingame.m_AdvancementLevel;
				const int sum_level = domain_level + advance_level;

				const int skill_learn_level = (*g_pSkillInfoTable)[SkillID].GetLearnLevel();
				SKILLDOMAIN m_skill_domain = SKILLDOMAIN_VAMPIRE;
				MSkillDomain::SKILLSTATUS status = (*g_pSkillManager)[SKILLDOMAIN_VAMPIRE].GetSkillStatus(SkillID);

				if (m_advance_skill_id_vec.size() > 0)
				{
					if (MSkillDomain::SKILLSTATUS::SKILLSTATUS_LEARNED != status &&
						skill_learn_level >= 0 && domain_level >= 150 && advance_level > 0 &&
						skill_learn_level <= sum_level)
					{
						m_selected_grade_skill = SkillID;
						m_selected_skill_domain = m_skill_domain;
						DeleteNew(m_pC_learn_grade_skill_confirm);

						m_pC_learn_grade_skill_confirm = new C_VS_UI_DIALOG(-1, -1, 3, 0, ExecF_LearnAdvenceSkillConfirm, DIALOG_OK | DIALOG_CANCEL);

						if (g_eRaceInterface == RACE_VAMPIRE && C_VS_UI_MILITARYDLG::m_vampire_ACType == -1)
						{
							bool bWarrior = (*g_pSkillInfoTable)[SkillID].GetSkillStep() == SKILL_STEP_VAMPIRE_WARRIOR_ADVANCEMENT;
							LPCSTR pACType = bWarrior ?
								(*g_pGameStringTable)[UI_STRING_MESSAGE_ACVAMPIRE_WARRIOR_TYPE].GetString() :
								(*g_pGameStringTable)[UI_STRING_MESSAGE_ACVAMPIRE_MAGICIAN_TYPE].GetString();

							std::string formatStr = (*g_pGameStringTable)[UI_STRING_MESSAGE_LEARN_SKILL_ACVAMPIRE].GetString();
							std::string msg;
							{
								size_t pos1 = formatStr.find("%s");
								if (pos1 != std::string::npos) {
									msg = formatStr.substr(0, pos1) + pACType + formatStr.substr(pos1 + 2);
									size_t pos2 = msg.find("%s", pos1);
									if (pos2 != std::string::npos) {
										msg = msg.substr(0, pos2) + pACType + msg.substr(pos2 + 2);
									}
								}
								else {
									msg = formatStr;
								}
							}
							const char* ppmsg[] = { msg.c_str() };
							m_pC_learn_grade_skill_confirm->SetMessage(const_cast<char**>(ppmsg), 1, SMO_FIT, 2);
						}
						else
						{
							std::string msg = (*g_pGameStringTable)[UI_STRING_MESSAGE_LEARN_SKILL].GetString();
							const char* ppmsg[] = { msg.c_str() };
							m_pC_learn_grade_skill_confirm->SetMessage(const_cast<char**>(ppmsg), 1, SMO_NOFIT);
						}
						m_pC_learn_grade_skill_confirm->WH(400, 140);
						m_pC_learn_grade_skill_confirm->Start();
					}
				}
			}
			break;
		}

		case RACE_SLAYER:
		{
			if (!m_advance_skill_id_vec.empty() && id <= Button_Vampire_adv_skill_5 && id >= Button_Vampire_adv_skill_1)
			{
				if ((*g_pSkillManager)[SKILLDOMAIN_BLADE].GetDomainLevel() == 150)
					m_skill_domain = SKILLDOMAIN_BLADE;
				else if ((*g_pSkillManager)[SKILLDOMAIN_SWORD].GetDomainLevel() == 150)
					m_skill_domain = SKILLDOMAIN_SWORD;
				else if ((*g_pSkillManager)[SKILLDOMAIN_GUN].GetDomainLevel() == 150)
					m_skill_domain = SKILLDOMAIN_GUN;
				else if ((*g_pSkillManager)[SKILLDOMAIN_HEAL].GetDomainLevel() == 150)
					m_skill_domain = SKILLDOMAIN_HEAL;
				else if ((*g_pSkillManager)[SKILLDOMAIN_ENCHANT].GetDomainLevel() == 150)
					m_skill_domain = SKILLDOMAIN_ENCHANT;

				MSkillDomain::SKILL_STEP_LIST::iterator ss = m_advance_skill_id_vec.begin() + (id - Button_Vampire_adv_skill_1);
				const ACTIONINFO SkillID = (ACTIONINFO)*ss;
				m_selected_ACSkillID = SkillID;
				const int domain_level = (*g_pSkillManager)[m_skill_domain].GetDomainLevel();
				const int advance_level = g_char_slot_ingame.m_AdvancementLevel;
				const int sum_level = domain_level + advance_level;

				const int skill_learn_level = (*g_pSkillInfoTable)[SkillID].GetLearnLevel();
				MSkillDomain::SKILLSTATUS status;
				if (SkillID == 591 || SkillID == 728)
				{
					status = (*g_pSkillManager)[SKILLDOMAIN_ETC].GetSkillStatus(SkillID);
				}
				else
				{
					status = (*g_pSkillManager)[m_skill_domain].GetSkillStatus(SkillID);
				}

				if (m_advance_skill_id_vec.size() > 0)
				{
					if (MSkillDomain::SKILLSTATUS::SKILLSTATUS_LEARNED != status &&
						skill_learn_level >= 0 && domain_level >= 150 && advance_level > 0 &&
						skill_learn_level <= sum_level)
					{
						m_selected_grade_skill = SkillID;
						m_selected_skill_domain = m_skill_domain;
						DeleteNew(m_pC_learn_grade_skill_confirm);

						m_pC_learn_grade_skill_confirm = new C_VS_UI_DIALOG(-1, -1, 3, 0, ExecF_LearnAdvenceSkillConfirm, DIALOG_OK | DIALOG_CANCEL);

						std::string msg = (*g_pGameStringTable)[UI_STRING_MESSAGE_LEARN_SKILL].GetString();
						const char* ppmsg[] = { msg.c_str() };
						m_pC_learn_grade_skill_confirm->SetMessage(const_cast<char**>(ppmsg), 1, SMO_NOFIT);
						m_pC_learn_grade_skill_confirm->Start();
					}
				}
			}
			break;
		}

		case RACE_OUSTERS:
		{
			if (!m_advance_skill_id_vec.empty() && id <= Button_Vampire_adv_skill_5 && id >= Button_Vampire_adv_skill_1)
			{
				MSkillDomain::SKILL_STEP_LIST::iterator ss = m_advance_skill_id_vec.begin() + (id - Button_Vampire_adv_skill_1);
				const ACTIONINFO SkillID = (ACTIONINFO)*ss;
				m_selected_ACSkillID = SkillID;
				const int domain_level = (*g_pSkillManager)[SKILLDOMAIN_OUSTERS].GetDomainLevel();
				const int advance_level = g_char_slot_ingame.m_AdvancementLevel;
				const int sum_level = domain_level + advance_level;

				const int skill_learn_level = (*g_pSkillInfoTable)[SkillID].GetLearnLevel();
				SKILLDOMAIN m_skill_domain = SKILLDOMAIN_OUSTERS;
				MSkillDomain::SKILLSTATUS status = (*g_pSkillManager)[SKILLDOMAIN_OUSTERS].GetSkillStatus(SkillID);

				if (m_advance_skill_id_vec.size() > 0)
				{
					if (MSkillDomain::SKILLSTATUS::SKILLSTATUS_LEARNED != status &&
						skill_learn_level >= 0 && domain_level >= 150 && advance_level > 0 &&
						skill_learn_level <= sum_level)
					{
						m_selected_grade_skill = SkillID;
						m_selected_skill_domain = m_skill_domain;
						DeleteNew(m_pC_learn_grade_skill_confirm);

						m_pC_learn_grade_skill_confirm = new C_VS_UI_DIALOG(-1, -1, 3, 0, ExecF_LearnAdvenceSkillConfirm, DIALOG_OK | DIALOG_CANCEL);

						std::string msg = (*g_pGameStringTable)[UI_STRING_MESSAGE_LEARN_SKILL].GetString();
						const char* ppmsg[] = { msg.c_str() };
						m_pC_learn_grade_skill_confirm->SetMessage(const_cast<char**>(ppmsg), 1, SMO_NOFIT);
						m_pC_learn_grade_skill_confirm->Start();
					}
				}
			}
			break;
		}
		} // switch (g_eRaceInterface) KAPANMA PARANTEZİ (DÜZELTİLDİ)
		break;
	}
	} // switch (id) KAPANMA PARANTEZİ
}

