bool C_VS_UI_TMALL::MouseControl(UINT message, int _x, int _y)
{
	Window::MouseControl(message, _x, _y);
	_x-=x; _y-=y;

	bool re = m_pC_button_group->MouseControl(message, _x, _y);

	int px = _x + x;
	int py = _y + y;

	switch(message)
	{
	case M_MOVING:
		for (int i=0; i<9; i++)
		{
			if ( m_slot_rect[i].IsInRect(px, py) )
			{
				int nRealIndex = m_nPageIndex * PageSize + i;
				int nSize = m_ItemList.size();
				if ( nRealIndex < nSize )
				{
					MItem* p_item = m_ItemList[nRealIndex].pItem;
					if ( p_item )
						g_descriptor_manager.Set(DID_ITEM, x+m_slot_rect[i].x, y+m_slot_rect[i].y, (void *)p_item, 0, (int)0);
				}
			}
		}
		break;

	case M_LEFTBUTTON_DOWN:
		// 2026-09-03 R7 — kullanici istegi: Market (TMall) tasinabilir.
		// Minimap drag pattern'inin aynisi: buton tuketmediyse (re=true)
		// ve item tasinmiyorken drag baslar. Yalniz UST SERIT (_y < 100,
		// kategori butonlari 106'da baslar) — item slot tiklamalari drag'a
		// donusmesin. Ekran siniri clamp + kenara yapisma Window::Move'da.
		if (gpC_mouse_pointer->GetPickUpItem() == NULL && re && _y < 100)
		{
			MoveReady();
			SetOrigin(_x, _y);
		}
		break;
	}

	return true;
}

