C_VS_UI_MINIMAP::C_VS_UI_MINIMAP()
{
#if __CONTENTS(__GPS_ADD)	
	gwMiniMapCount++;
#endif //__GPS_ADD

	m_pC_minimap_spk = NULL;
	AttrTopmost(false);
	AttrPin(false);

	// 2026-09-03 — skill-follow baglantisi TRIBE ctor'da SetSkillFollow ile kurulur
	m_pSkillFollow = NULL;
	m_SkillFollowOffX = 0;
	m_SkillFollowOffY = 0;

	g_RegisterWindow(this);
	

	m_pC_minimap_spk = new C_SPRITE_PACK(SPK_MINIMAP_VAMPIRE);


	//Set(RESOLUTION_X-m_pC_minimap_spk->GetWidth(MINIMAP_MAIN)-m_pC_minimap_spk->GetWidth(MINIMAP_RIGHT), 0, m_pC_minimap_spk->GetWidth(MINIMAP_MAIN)+m_pC_minimap_spk->GetWidth(MINIMAP_RIGHT), m_pC_minimap_spk->GetHeight(MINIMAP_MAIN));
	
	Set(g_pUserInformation->iResolution_x-m_pC_minimap_spk->GetWidth(MINIMAP_MAIN)-2,g_pUserInformation->iResolution_y- m_pC_minimap_spk->GetHeight(MINIMAP_MAIN)-2, m_pC_minimap_spk->GetWidth(MINIMAP_MAIN), m_pC_minimap_spk->GetHeight(MINIMAP_MAIN));

	//skillinfo ��ư
	m_pC_button_group = new ButtonGroup(this);
	
	//m_pC_button_group->Add(new C_VS_UI_EVENT_BUTTON(x, y+10, m_pC_minimap_spk->GetWidth(MINIMAP_HIDE_ID), m_pC_minimap_spk->GetHeight(MINIMAP_HIDE_ID), PUSHPIN_ID, this, MINIMAP_HIDE_ID));
	m_pC_button_group->Add(new C_VS_UI_EVENT_BUTTON(x,y+133,m_pC_minimap_spk->GetWidth(MINIMAP_GAME_OPTIONS),m_pC_minimap_spk->GetHeight(MINIMAP_GAME_OPTIONS),GAME_OPTIONS_SHOW,this,MINIMAP_GAME_OPTIONS));

	m_zone_id = -1;


	m_map_x = 0; m_map_y = 0;
	m_map_w = 0; m_map_h = 0;
	m_map_start_point.x = 7;
	m_map_start_point.y = 30;

	m_bl_refresh = false;
	
	m_bl_slot_hide = false;
	// TIMER
	m_dw_minimap_prev_tickcount = GetTickCount();
	m_dw_minimap_millisec = 100;
	
	m_p_minimap_surface = new CSpriteSurface;
	
	m_p_minimap_surface->InitOffsurface(200, 100, DDSCAPS_SYSTEMMEMORY);
	m_p_minimap_surface->SetTransparency(0xffff);
	
	m_surface_w = 200;
	// FIX 2026-05-12: copy-paste bug; `m_surface_w` yerine `m_surface_h`. m_surface_h uninit kaldığı için
	// pre-zone-load minimap render'da rt={0,0,m_surface_w,m_surface_h} garbage h değeri kullanıyordu.
	m_surface_h = 100;
	m_Block.clear();
	m_Flag.clear();

	
#ifndef _LIB
	m_map_w = 256;
	m_map_h = 256;
	SetZone(11);
	RECT rect = {110,110,140,150};
	SetSafetyZone(rect, true);
	SetRect(&rect, 10, 10, 30, 30);
	SetPortal(rect, 1001);
	MINIMAP_NPC npc;//{20, 50, 157};
	npc.x=20;
	npc.y=50;
	npc.id=157;
	npc.name = "sonee";
	SetNPC(npc);
#endif
	
}

