void	C_VS_UI_TEAM_LIST::Start()
{
	PI_Processor::Start();
	m_pC_button_group->Init();
	
	AttrTopmost(true);
	AttrKeyboardControl(true);
	gpC_window_manager->AppearWindow(this);
	
	m_lev_search.Acquire();
	m_lev_search.EraseAll();
	
}

