//-----------------------------------------------------------------------------
// OtherCharInfo.spk hucre olculeri (sprite 0 = 275x327, 1px grid taramasi).
// Ust tablo 3x2: x 126|166|258, y 28/46/64/82 (satir 18).
// Alt liste 10x1: x 126..258, y 91 + n*19 (satir 19).
//-----------------------------------------------------------------------------
namespace OtherCharInfoTestLayout
{
	const int kPortX = 29, kPortY = 28, kPortW = 64, kPortH = 76;
	const int kFaceW = 55, kFaceH = 70;
	const int kMarkY = 108, kMarkSize = 40;
	const int kGuildX = 31, kGradeX = 71;

	const int kTX0 = 126, kTXm = 166, kTX1 = 258;
	const int kTY0 = 28, kTRowH = 18, kTRows = 3;

	const int kLX0 = 126, kLX1 = 258;
	const int kLY0 = 91, kLRowH = 19, kLRows = 10;
	const int kPad = 4;

	inline HFONT Font() { return gpC_base->m_chatting_pi.hfont; }

	inline int FontH()
	{
		const int h = g_GetStringHeight("A", Font());
		return h > 0 ? h : 12;
	}

	inline int CellTextY(int cell_top, int cell_h)
	{
		int dy = (cell_h - FontH()) / 2;
		if (dy < 1)
			dy = 1;
		return cell_top + dy;
	}

	inline int TopTextY(int row) { return CellTextY(kTY0 + row * kTRowH, kTRowH); }
	inline int ListTextY(int row) { return CellTextY(kLY0 + row * kLRowH, kLRowH); }
	inline int TopLabelX() { return kTX0 + kPad; }
	inline int TopValueX() { return kTXm + kPad; }
	inline int TopLabelMaxW() { return kTXm - kTX0 - kPad * 2; }
	inline int TopValueMaxW() { return kTX1 - kTXm - kPad * 2; }
	inline int ListLabelX() { return kLX0 + kPad; }

	inline bool HitText(int mx, int my, int tx, int ty, const char* s, int max_w)
	{
		if (s == NULL || s[0] == 0)
			return false;
		int tw = g_GetStringWidth(s, Font());
		if (max_w > 0 && tw > max_w)
			tw = max_w;
		const int th = FontH();
		return mx >= tx && mx < tx + tw && my >= ty && my < ty + th;
	}

	inline bool HitTopRow(int mx, int my, int row, const char* label, const char* value)
	{
		const int ty = TopTextY(row);
		return HitText(mx, my, TopLabelX(), ty, label, TopLabelMaxW())
			|| HitText(mx, my, TopValueX(), ty, value, TopValueMaxW());
	}

	inline bool HitListRow(int mx, int my, int row, const char* label, const char* value)
	{
		const int ty = ListTextY(row);
		const int label_w = g_GetStringWidth(label ? label : "", Font());
		int vw = value ? g_GetStringWidth(value, Font()) : 0;
		int value_max = kLX1 - kPad - (kLX0 + kPad + label_w + kPad);
		if (value_max < 8)
			value_max = 8;
		if (vw > value_max)
			vw = value_max;
		const int vx = kLX1 - kPad - vw;
		return HitText(mx, my, ListLabelX(), ty, label, label_w)
			|| (value && value[0] && HitText(mx, my, vx, ty, value, vw));
	}

	static void PrintClipped(int px, int py, const char* text, int max_w)
	{
		if (text == NULL || text[0] == 0 || max_w <= 0)
			return;
		if (g_GetStringWidth(text, Font()) <= max_w)
		{
			g_PrintColorStr(px, py, text, gpC_base->m_chatting_pi, RGB_WHITE);
			return;
		}
		char buf[128];
		size_t n = strlen(text);
		if (n >= sizeof(buf))
			n = sizeof(buf) - 1;
		memcpy(buf, text, n);
		buf[n] = 0;
		while (n > 0 && g_GetStringWidth(buf, Font()) > max_w)
		{
			--n;
			buf[n] = 0;
		}
		g_PrintColorStr(px, py, buf, gpC_base->m_chatting_pi, RGB_WHITE);
	}

	static void PrintTopRow(int win_x, int win_y, int row, const char* label, const char* value)
	{
		const int ty = win_y + TopTextY(row);
		PrintClipped(win_x + TopLabelX(), ty, label, TopLabelMaxW());
		PrintClipped(win_x + TopValueX(), ty, value, TopValueMaxW());
	}

	static void PrintListRow(int win_x, int win_y, int row, const char* label, const char* value)
	{
		const int ty = win_y + ListTextY(row);
		const int label_w = g_GetStringWidth(label ? label : "", Font());
		PrintClipped(win_x + ListLabelX(), ty, label, kLX1 - kLX0 - kPad * 2);
		if (value == NULL || value[0] == 0)
			return;
		int vw = g_GetStringWidth(value, Font());
		int value_max = kLX1 - kPad - (kLX0 + kPad + label_w + kPad);
		if (value_max < 8)
			value_max = 8;
		if (vw > value_max)
			vw = value_max;
		const int vx = win_x + kLX1 - kPad - vw;
		PrintClipped(vx, ty, value, vw);
	}
}

//-----------------------------------------------------------------------------
// ShowOtherCharInfoTest
//
// TEST: Other Info'yu OtherCharInfo.spk hucrelerine basar. Alanlar irk orijinal
// Other Info ile ayni (Slayer Team+Fame, Vampire Clan, Ousters Guild).
// AssembleMessageBox + Info*.spk yolu asagida duruyor.
//-----------------------------------------------------------------------------
void	C_VS_UI_OTHER_INFO::ShowOtherCharInfoTest(const char* align_temp[5], const char* Origin_Server[5], const char* grade[20])
{
	using namespace OtherCharInfoTestLayout;
	char sz_temp[100];
	CSprite* GradeMark = NULL;

	const char* group_label = "Clan";
	const char* group_empty = (*g_pGameStringTable)[UI_STRING_MESSAGE_NOT_JOIN_ANY_CLAN].GetString();
	if (g_eRaceInterface == RACE_SLAYER)
	{
		group_label = "Team";
		group_empty = (*g_pGameStringTable)[UI_STRING_MESSAGE_NOT_JOIN_ANY_TEAM].GetString();
	}
	else if (g_eRaceInterface == RACE_OUSTERS)
	{
		group_label = "Guild";
		group_empty = (*g_pGameStringTable)[UI_STRING_MESSAGE_NOT_JOIN_ANY_GUILD].GetString();
	}

	m_otherCharInfoSpk.Blt(x, y, 0);

	POINT face_pt = { x + kPortX + (kPortW - kFaceW) / 2, y + kPortY + (kPortH - kFaceH) / 2 };
	POINT guild_pt = { x + kGuildX, y + kMarkY };
	POINT grade_pt = { x + kGradeX, y + kMarkY };

	if (gpC_base->m_p_DDSurface_back->Lock())
	{
		if (m_p_face && m_p_face->GetSize() > 0)
			gpC_base->m_p_DDSurface_back->BltSprite(&face_pt, &(*m_p_face)[0]);

		if (m_player_info.GRADE > 0 && m_player_info.GRADE <= GRADE_MARK_MAX)
		{
			GradeMark = g_pGuildMarkManager->GetGradeMark(m_player_info.GRADE - 1, g_eRaceInterface);
			if (GradeMark != NULL)
				gpC_base->m_p_DDSurface_back->BltSprite(&grade_pt, GradeMark);
		}

		RECT guild_rect = { guild_pt.x, guild_pt.y, guild_pt.x + kMarkSize, guild_pt.y + kMarkSize };
		DrawAlphaBox(&guild_rect, 0, 0, 2, 16);
		if (m_p_guild_mark != NULL)
			gpC_base->m_p_DDSurface_back->BltSprite(&guild_pt, m_p_guild_mark);

		m_pC_button_group->Show();
		gpC_base->m_p_DDSurface_back->Unlock();
	}

	g_FL2_GetDC();

	const char* name_val = m_player_info.PLAYER_NAME.empty() ? "" : m_player_info.PLAYER_NAME.c_str();
	const char* grade_val = "";
	if (m_player_info.GRADE > 0 && m_player_info.GRADE <= GRADE_MARK_MAX)
		grade_val = grade[(m_player_info.GRADE - 1) / 5];
	const char* group_val = g_pGuildInfoMapper->IsExistGuildName(m_player_info.guild_id)
		? g_pGuildInfoMapper->GetGuildName(m_player_info.guild_id)
		: group_empty;

	PrintTopRow(x, y, 0, "Name", name_val);
	PrintTopRow(x, y, 1, "Grade", grade_val);
	PrintTopRow(x, y, 2, group_label, group_val);

	int list_row = 0;
	if (g_eRaceInterface == RACE_SLAYER && TopDomain >= 0 && TopDomain < 5)
	{
		const static char* SlayerJob[5] = {
			(*g_pGameStringTable)[UI_STRING_MESSAGE_ENG_DOMAIN_BLADE2].GetString(),
			(*g_pGameStringTable)[UI_STRING_MESSAGE_ENG_DOMAIN_SWORD2].GetString(),
			(*g_pGameStringTable)[UI_STRING_MESSAGE_ENG_DOMAIN_GUN2].GetString(),
			(*g_pGameStringTable)[UI_STRING_MESSAGE_ENG_DOMAIN_HEAL2].GetString(),
			(*g_pGameStringTable)[UI_STRING_MESSAGE_ENG_DOMAIN_ENCHANT2].GetString(),
		};
		sprintf(sz_temp, "%s %s %d", SlayerJob[TopDomain],
			(*g_pGameStringTable)[UI_STRING_MESSAGE_DESC_CLASS2].GetString(),
			m_player_info.DOMAINLEVEL[TopDomain]);
	}
	else
		sprintf(sz_temp, "%d", m_player_info.LEVEL);
	PrintListRow(x, y, list_row++, "Level", sz_temp);

	if (g_eRaceInterface == RACE_SLAYER)
	{
		sprintf(sz_temp, "%d", m_player_info.FAME);
		std::string sstr = sz_temp;
		for (int i = 3; i <= 13; i += 4)
			if (sstr.size() > (size_t)i) sstr.insert(sstr.size() - i, ",");
		PrintListRow(x, y, list_row++, "Fame", sstr.c_str());
	}

	sprintf(sz_temp, "%d/%d", m_player_info.STR_PURE, m_player_info.STR_CUR);
	PrintListRow(x, y, list_row++, "STR", sz_temp);

	sprintf(sz_temp, "%d/%d", m_player_info.DEX_PURE, m_player_info.DEX_CUR);
	PrintListRow(x, y, list_row++, "DEX", sz_temp);

	sprintf(sz_temp, "%d/%d", m_player_info.INT_PURE, m_player_info.INT_CUR);
	PrintListRow(x, y, list_row++, "INT", sz_temp);

	const char* align_val = "";
	if (m_player_info.ALIGNMENT >= 0 && m_player_info.ALIGNMENT < 5)
		align_val = align_temp[m_player_info.ALIGNMENT];
	PrintListRow(x, y, list_row++, "Align", align_val);

	if (!g_pUserInformation->IsNetmarble && !g_pUserInformation->IsTestServer)
	{
		const char* origin_val = "";
		if (m_player_info.Origin_ServerIdx >= 1 && m_player_info.Origin_ServerIdx <= 5)
			origin_val = Origin_Server[m_player_info.Origin_ServerIdx - 1];
		PrintListRow(x, y, list_row++, "Origin", origin_val);
	}

#if __CONTENTS(__CONTRIBUTE_SYSTEM)
	{
		int contributeGrade = countContributeGrade(m_player_info.contributePoint);
		sprintf(sz_temp, "%d/%d", m_player_info.contributePoint, contributeGrade);
		PrintListRow(x, y, list_row++, "Contribute", sz_temp);
	}
#endif

	m_pC_button_group->ShowDescription();
	g_FL2_ReleaseDC();
}

